{"command":"create","path":"/workspace/backend/cmd/server/main.go","file_text":"package main

import (
	"context"
	"log"
	"net/http"
	"os"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
)

type App struct {
	DB  *pgxpool.Pool
	Hub *Hub
}

func main() {
	ctx := context.Background()

	dbURL := os.Getenv("DATABASE_URL")
	if dbURL == "" {
		dbURL = "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"
	}

	pool, err := pgxpool.New(ctx, dbURL)
	if err != nil {
		log.Fatalf("failed to connect to database: %v", err)
	}
	defer pool.Close()

	// Wait for DB to be reachable (helps with container startup ordering).
	deadline := time.Now().Add(30 * time.Second)
	for {
		if err := pool.Ping(ctx); err == nil {
			break
		}
		if time.Now().After(deadline) {
			log.Fatalf("database not reachable: %v", err)
		}
		time.Sleep(500 * time.Millisecond)
	}

	app := &App{DB: pool, Hub: NewHub()}

	if err := app.ensureInitialAdmin(ctx); err != nil {
		log.Fatalf("failed to ensure initial admin: %v", err)
	}
	if err := app.ensureDefaultSampleTypes(ctx); err != nil {
		log.Fatalf("failed to seed default sample types: %v", err)
	}

	mux := http.NewServeMux()
	app.registerRoutes(mux)

	addr := os.Getenv("LISTEN_ADDR")
	if addr == "" {
		addr = "127.0.0.1:8080"
	}

	srv := &http.Server{
		Addr:              addr,
		Handler:           mux,
		ReadHeaderTimeout: 10 * time.Second,
	}

	log.Printf("listening on %s", addr)
	if err := srv.ListenAndServe(); err != nil {
		log.Fatalf("server error: %v", err)
	}
}
"}

{"command":"create","path":"/workspace/backend/cmd/server/httpjson.go","file_text":"package main

import (
	"encoding/json"
	"net/http"
)

// writeData wraps the given value in {"data": ...} per the pinned contract.
func writeData(w http.ResponseWriter, status int, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(map[string]interface{}{"data": v})
}

// apiError represents a structured error to return to the client.
type apiError struct {
	Status int
	Code   string
	Msg    string
}

func (e *apiError) Error() string { return e.Msg }

func newErr(status int, code, msg string) *apiError {
	return &apiError{Status: status, Code: code, Msg: msg}
}

func writeErr(w http.ResponseWriter, err *apiError) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(err.Status)
	_ = json.NewEncoder(w).Encode(map[string]interface{}{
		"error": err.Msg,
		"code":  err.Code,
	})
}

var (
	errInvalidJSON  = newErr(http.StatusBadRequest, "invalid_json", "request body is not valid JSON")
	errUnauthorized = newErr(http.StatusUnauthorized, "unauthorized", "authentication required")
	errForbidden    = newErr(http.StatusForbidden, "forbidden", "not permitted for the active role")
	errNotFound     = newErr(http.StatusNotFound, "not_found", "resource not found")
	errRoleNotSel   = newErr(http.StatusConflict, "role_not_selected", "an active role must be selected")
	errInternal     = newErr(http.StatusInternalServerError, "internal_error", "internal error")
	errIdemRequired = newErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
)

func decodeJSON(r *http.Request, v interface{}) error {
	dec := json.NewDecoder(r.Body)
	return dec.Decode(v)
}
"}

{"command":"create","path":"/workspace/backend/cmd/server/auth.go","file_text":"package main

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"net/http"
	"os"
	"strings"
	"time"

	"github.com/google/uuid"
	"golang.org/x/crypto/bcrypt"
)

type Session struct {
	Token      string
	UserID     uuid.UUID
	ActiveRole string
}

type CurrentUser struct {
	ID            uuid.UUID
	Username      string
	FullName      string
	Roles         []string
	ActiveRole    string
	SessionToken  string
	AssignedLoc   *uuid.UUID
}

func hashPassword(pw string) (string, error) {
	b, err := bcrypt.GenerateFromPassword([]byte(pw), bcrypt.DefaultCost)
	return string(b), err
}

func checkPassword(hash, pw string) bool {
	return bcrypt.CompareHashAndPassword([]byte(hash), []byte(pw)) == nil
}

func newToken() string {
	b := make([]byte, 32)
	_, _ = rand.Read(b)
	return hex.EncodeToString(b)
}

// ensureInitialAdmin creates the first administrator account from
// ADMIN_USERNAME / ADMIN_PASSWORD if no users exist yet. Safe to call on
// every startup: it never creates a duplicate administrator.
func (a *App) ensureInitialAdmin(ctx context.Context) error {
	var count int
	if err := a.DB.QueryRow(ctx, `SELECT count(*) FROM users`).Scan(&count); err != nil {
		return err
	}
	if count > 0 {
		return nil
	}
	username := os.Getenv("ADMIN_USERNAME")
	password := os.Getenv("ADMIN_PASSWORD")
	if username == "" {
		username = "admin"
	}
	if password == "" {
		password = "admin"
	}
	hash, err := hashPassword(password)
	if err != nil {
		return err
	}
	var id uuid.UUID
	err = a.DB.QueryRow(ctx, `INSERT INTO users (username, password_hash, full_name, active)
		VALUES ($1, $2, $3, TRUE) RETURNING id`, username, hash, "Administrator").Scan(&id)
	if err != nil {
		return err
	}
	_, err = a.DB.Exec(ctx, `INSERT INTO user_roles (user_id, role) VALUES ($1, 'administrator')`, id)
	return err
}

func (a *App) loadUser(ctx context.Context, token string) (*CurrentUser, error) {
	var userID uuid.UUID
	var activeRole *string
	err := a.DB.QueryRow(ctx, `SELECT user_id, active_role FROM sessions WHERE token=$1`, token).Scan(&userID, &activeRole)
	if err != nil {
		return nil, err
	}
	var username, fullName string
	var active bool
	var assignedLoc *uuid.UUID
	err = a.DB.QueryRow(ctx, `SELECT username, coalesce(full_name,''), active, assigned_location_id FROM users WHERE id=$1`, userID).
		Scan(&username, &fullName, &active, &assignedLoc)
	if err != nil {
		return nil, err
	}
	if !active {
		return nil, errUnauthorized
	}
	rows, err := a.DB.Query(ctx, `SELECT role FROM user_roles WHERE user_id=$1`, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var roles []string
	for rows.Next() {
		var r string
		if err := rows.Scan(&r); err != nil {
			return nil, err
		}
		roles = append(roles, r)
	}
	cu := &CurrentUser{
		ID:           userID,
		Username:     username,
		FullName:     fullName,
		Roles:        roles,
		SessionToken: token,
		AssignedLoc:  assignedLoc,
	}
	if activeRole != nil {
		cu.ActiveRole = *activeRole
	}
	_, _ = a.DB.Exec(ctx, `UPDATE sessions SET last_seen_at=now() WHERE token=$1`, token)
	return cu, nil
}

func bearerToken(r *http.Request) string {
	h := r.Header.Get("Authorization")
	if strings.HasPrefix(h, "Bearer ") {
		return strings.TrimPrefix(h, "Bearer ")
	}
	return ""
}

// requireAuth extracts and validates the bearer [REDACTED], returning the current user.
func (a *App) requireAuth(w http.ResponseWriter, r *http.Request) (*CurrentUser, bool) {
	token := bearerToken(r)
	if token == "" {
		writeErr(w, errUnauthorized)
		return nil, false
	}
	cu, err := a.loadUser(r.Context(), token)
	if err != nil {
		writeErr(w, errUnauthorized)
		return nil, false
	}
	return cu, true
}

func hasRole(cu *CurrentUser, role string) bool {
	for _, r := range cu.Roles {
		if r == role {
			return true
		}
	}
	return false
}

// requireActiveRole ensures the user has selected an active role and that it
// is among the allowed set (if provided).
func requireActiveRole(w http.ResponseWriter, cu *CurrentUser, allowed ...string) bool {
	if cu.ActiveRole == "" {
		writeErr(w, errRoleNotSel)
		return false
	}
	if len(allowed) == 0 {
		return true
	}
	for _, role := range allowed {
		if cu.ActiveRole == role {
			return true
		}
	}
	writeErr(w, errForbidden)
	return false
}

func isAdminOrDispatcher(role string) bool {
	return role == "administrator" || role == "dispatcher"
}

var _ = time.Now
"}

