		VALUES ($1, $2, $3, $4, $5, $6, $7)`, actorID, role, action, entityType, entityID, success, b)
}

// recordTimeline appends an entry to an entity's ordered status-history timeline.
func (a *App) recordTimeline(ctx context.Context, entityType string, entityID uuid.UUID, action string, actorID *uuid.UUID, role string, success bool, details map[string]interface{}) {
	if details == nil {
		details = map[string]interface{}{}
	}
	b, _ := json.Marshal(details)
	_, _ = a.DB.Exec(ctx, `INSERT INTO timeline_entries (entity_type, entity_id, action, actor_id, role, success, details)
		VALUES ($1, $2, $3, $4, $5, $6, $7)`, entityType, entityID, action, actorID, role, success, b)
}

type TimelineEntry struct {
	EventID   int64                  `json:"eventId"`
	Action    string                 `json:"action"`
	ActorID   string                 `json:"actorId"`
	Role      string                 `json:"role"`
	EntityType string                `json:"entityType"`
	EntityID  string                 `json:"entityId"`
	Success   bool                   `json:"success"`
	OccurredAt string                `json:"occurredAt"`
	Details   map[string]interface{} `json:"details"`
}

func (a *App) getTimeline(ctx context.Context, entityType string, entityID uuid.UUID) ([]TimelineEntry, error) {
	rows, err := a.DB.Query(ctx, `SELECT id, action, coalesce(actor_id::text,''), coalesce(role,''), entity_type, entity_id::text, success, occurred_at, details
		FROM timeline_entries WHERE entity_type=$1 AND entity_id=$2 ORDER BY id ASC`, entityType, entityID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []TimelineEntry
	for rows.Next() {
		var t TimelineEntry
		var details []byte
		var occurredAt interface{}
		if err := rows.Scan(&t.EventID, &t.Action, &t.ActorID, &t.Role, &t.EntityType, &t.EntityID, &t.Success, &occurredAt, &details); err != nil {
			return nil, err
		}
		t.OccurredAt = formatTime(occurredAt)
		_ = json.Unmarshal(details, &t.Details)
		if t.Details == nil {
			t.Details = map[string]interface{}{}
		}
		out = append(out, t)
	}
	return out, nil
}
"}

{"command":"create","path":"/workspace/backend/cmd/server/util.go","file_text":"package main

import (
	"math"
	"time"
)

const rfc3339 = time.RFC3339

func formatTime(v interface{}) string {
	switch t := v.(type) {
	case time.Time:
		return t.UTC().Format(rfc3339)
	case *time.Time:
		if t == nil {
			return ""
		}
		return t.UTC().Format(rfc3339)
	default:
		return ""
	}
}

func parseTime(s string) (time.Time, error) {
	return time.Parse(time.RFC3339, s)
}

// haversineKm returns the great-circle distance between two coordinates in km.
func haversineKm(lat1, lon1, lat2, lon2 float64) float64 {
	const R = 6371.0
	dLat := (lat2 - lat1) * math.Pi / 180
	dLon := (lon2 - lon1) * math.Pi / 180
	lat1r := lat1 * math.Pi / 180
	lat2r := lat2 * math.Pi / 180
	sinDLat := math.Sin(dLat / 2)
	sinDLon := math.Sin(dLon / 2)
	aa := sinDLat*sinDLat + math.Cos(lat1r)*math.Cos(lat2r)*sinDLon*sinDLon
	c := 2 * math.Atan2(math.Sqrt(aa), math.Sqrt(1-aa))
	return R * c
}

func ptrString(s string) *string { return &s }
"}

{"command":"create","path":"/workspace/backend/cmd/server/realtime.go","file_text":"package main

import (
	"context"
	"encoding/json"
	"net/http"
	"strconv"
	"sync"

	"github.com/coder/websocket"
	"github.com/google/uuid"
)

// Hub fans out realtime events to connected websocket subscribers. Events are
// also durably persisted so that a client which reconnects with `since` can
// replay events it missed, and so that state survives a process restart.
type Hub struct {
	mu   sync.Mutex
	subs map[chan RealtimeEvent]subFilter
}

type subFilter struct {
	role   string
	userID uuid.UUID
}

type RealtimeEvent struct {
	ID         int64                  `json:"id"`
	Type       string                 `json:"type"`
	EntityType string                 `json:"entityType"`
	EntityID   string                 `json:"entityId"`
	Payload    map[string]interface{} `json:"payload"`
	CreatedAt  string                 `json:"createdAt"`
}

func NewHub() *Hub {
	return &Hub{subs: make(map[chan RealtimeEvent]subFilter)}
}

func (h *Hub) subscribe(role string, userID uuid.UUID) chan RealtimeEvent {
	ch := make(chan RealtimeEvent, 64)
	h.mu.Lock()
	h.subs[ch] = subFilter{role: role, userID: userID}
	h.mu.Unlock()
	return ch
}

func (h *Hub) unsubscribe(ch chan RealtimeEvent) {
	h.mu.Lock()
	delete(h.subs, ch)
	h.mu.Unlock()
	close(ch)
}

func (h *Hub) publish(ev RealtimeEvent) {
	h.mu.Lock()
	defer h.mu.Unlock()
	for ch := range h.subs {
		select {
		case ch <- ev:
		default:
		}
	}
}

// emit persists an event and fans it out to live subscribers.
func (a *App) emit(ctx context.Context, evType, entityType, entityID string, audienceRole string, audienceUser *uuid.UUID, payload map[string]interface{}) {
	if payload == nil {
		payload = map[string]interface{}{}
	}
	b, _ := json.Marshal(payload)
	var id int64
	var createdAt interface{}
	err := a.DB.QueryRow(ctx, `INSERT INTO realtime_events (type, entity_type, entity_id, audience_role, audience_user_id, payload)
		VALUES ($1,$2,$3,$4,$5,$6) RETURNING id, created_at`, evType, entityType, entityID, nullableStr(audienceRole), audienceUser, b).Scan(&id, &createdAt)
	if err != nil {
		return
	}
	a.Hub.publish(RealtimeEvent{
		ID: id, Type: evType, EntityType: entityType, EntityID: entityID,
		Payload: payload, CreatedAt: formatTime(createdAt),
	})
}

func nullableStr(s string) interface{} {
	if s == "" {
		return nil
	}
	return s
}

// handleEvents implements GET /api/events. It supports both a plain HTTP
// long-poll style response (returning buffered events since a cursor) and a
// websocket upgrade for live streaming, as described in the contract.
func (a *App) handleEvents(w http.ResponseWriter, r *http.Request) {
	cu, ok := a.requireAuth(w, r)
	if !ok {
		return
	}

	sinceStr := r.URL.Query().Get("since")
	var since int64
	if sinceStr != "" {
		since, _ = strconv.ParseInt(sinceStr, 10, 64)
	}

	if isWebsocketUpgrade(r) {
		a.serveEventsWebsocket(w, r, cu, since)
		return
	}

	events, cursor, err := a.replayEvents(r.Context(), since, cu)
	if err != nil {
		writeErr(w, errInternal)
		return
	}
	writeData(w, http.StatusOK, map[string]interface{}{"events": events, "cursor": cursor})
}

func isWebsocketUpgrade(r *http.Request) bool {
	return r.Header.Get("Upgrade") == "websocket" || r.Header.Get("Sec-WebSocket-Protocol") != ""
}

func (a *App) replayEvents(ctx context.Context, since int64, cu *CurrentUser) ([]RealtimeEvent, int64, error) {
	rows, err := a.DB.Query(ctx, `SELECT id, type, entity_type, entity_id, payload, created_at, coalesce(audience_role,''), audience_user_id
		FROM realtime_events WHERE id > $1 ORDER BY id ASC LIMIT 500`, since)
	if err != nil {
		return nil, since, err
	}
	defer rows.Close()
	cursor := since
	var out []RealtimeEvent
	for rows.Next() {
		var ev RealtimeEvent
		var payload []byte
		var createdAt interface{}
		var audRole string
		var audUser *uuid.UUID
		if err := rows.Scan(&ev.ID, &ev.Type, &ev.EntityType, &ev.EntityID, &payload, &createdAt, &audRole, &audUser); err != nil {
			return nil, since, err
		}
		if !eventVisible(cu, audRole, audUser) {
			cursor = ev.ID
			continue
		}
		_ = json.Unmarshal(payload, &ev.Payload)
		ev.CreatedAt = formatTime(createdAt)
		out = append(out, ev)
		cursor = ev.ID
	}
	return out, cursor, nil
}

func eventVisible(cu *CurrentUser, audRole string, audUser *uuid.UUID) bool {
	if audRole == "" && audUser == nil {
		return true
	}
	if audUser != nil && *audUser == cu.ID {
		return true
	}
	if audRole != "" && audRole == cu.ActiveRole {
		return true
	}
	if audRole != "" && isAdminOrDispatcher(cu.ActiveRole) {
		return true
	}
	return false
}

func (a *App) serveEventsWebsocket(w http.ResponseWriter, r *http.Request, cu *CurrentUser, since int64) {
	c, err := websocket.Accept(w, r, &websocket.AcceptOptions{
		Subprotocols:       []string{"lab-logistics-v1"},
		OriginPatterns:     []string{"*"},
		InsecureSkipVerify: true,
	})
	if err != nil {
		return
	}
	ctx := r.Context()
	defer c.CloseNow()

	events, cursor, err := a.replayEvents(ctx, since, cu)
	if err == nil {
		for _, ev := range events {
			b, _ := json.Marshal(ev)
			if c.Write(ctx, websocket.MessageText, b) != nil {
				return
			}
		}
	}

	ch := a.Hub.subscribe(cu.ActiveRole, cu.ID)
	defer a.Hub.unsubscribe(ch)

	for {
		select {
		case ev, okCh := <-ch:
			if !okCh {
				return
			}
			if ev.ID <= cursor {
				continue
			}
			b, _ := json.Marshal(ev)
			if c.Write(ctx, websocket.MessageText, b) != nil {
				return
			}
		case <-ctx.Done():
			return
		}
	}
}
"}

{"command":"create","path":"/workspace/backend/cmd/server/idempotency.go","file_text":"package main

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"

	"github.com/google/uuid"
)

// checkIdempotency looks up a previous response for the given key/endpoint.
// If found, ok=true and the caller should replay (status, response) verbatim.
func (a *App) checkIdempotency(ctx context.Context, key, endpoint string, userID uuid.UUID, body []byte) (status int, response json.RawMessage, ok bool, conflict bool) {
	if key == "" {
		return 0, nil, false, false
	}
	hash := sha256.Sum256(body)
	hashHex := hex.EncodeToString(hash[:])

	var storedHash string
	var storedStatus int
	var storedResp []byte
	err := a.DB.QueryRow(ctx, `SELECT request_hash, status_code, response FROM idempotency_keys
		WHERE idem_key=$1 AND endpoint=$2 AND user_id=$3`, key, endpoint, userID).Scan(&storedHash, &storedStatus, &storedResp)
	if err != nil {
		return 0, nil, false, false
	}
	if storedHash != hashHex {
		return 0, nil, false, true
	}
	return storedStatus, storedResp, true, false
}

func (a *App) saveIdempotency(ctx context.Context, key, endpoint string, userID uuid.UUID, body []byte, status int, response interface{}) {
	if key == "" {
		return
	}
	hash := sha256.Sum256(body)
	hashHex := hex.EncodeToString(hash[:])
	respBytes, _ := json.Marshal(response)
	_, _ = a.DB.Exec(ctx, `INSERT INTO idempotency_keys (idem_key, user_id, endpoint, request_hash, status_code, response)
		VALUES ($1,$2,$3,$4,$5,$6) ON CONFLICT (idem_key, endpoint, user_id) DO NOTHING`,
		key, userID, endpoint, hashHex, status, respBytes)
}
