{"command":"create","path":"/workspace/backend/cmd/server/handlers_auth.go","file_text":"package main

import (
	"encoding/json"
	"io"
	"net/http"
	"time"

	"github.com/google/uuid"
)

type authenticateReq struct {
	Username string `json:"username"`
	Password string `json:"password"`
}

func (a *App) handleAuthenticateUser(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	var req authenticateReq
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, errInvalidJSON)
		return
	}
	var userID uuid.UUID
	var hash string
	var active bool
	err := a.DB.QueryRow(ctx, `SELECT id, password_hash, active FROM users WHERE username=$1`, req.Username).Scan(&userID, &hash, &active)
	if err != nil || !active || !checkPassword(hash, req.Password) {
		a.recordAudit(ctx, nil, "", "sign_in", "user", req.Username, false, map[string]interface{}{"reason": "invalid_credentials"})
		writeErr(w, newErr(http.StatusUnauthorized, "invalid_credentials", "invalid username or password"))
		return
	}

	rows, err := a.DB.Query(ctx, `SELECT role FROM user_roles WHERE user_id=$1`, userID)
	if err != nil {
		writeErr(w, errInternal)
		return
	}
	var roles []string
	for rows.Next() {
		var role string
		_ = rows.Scan(&role)
		roles = append(roles, role)
	}
	rows.Close()

	token := newToken()
	var activeRole *string
	if len(roles) == 1 {
		activeRole = &roles[0]
	}
	_, err = a.DB.Exec(ctx, `INSERT INTO sessions (token, user_id, active_role) VALUES ($1,$2,$3)`, token, userID, activeRole)
	if err != nil {
		writeErr(w, errInternal)
		return
	}

	resp := map[string]interface{}{
		"sessionToken": token,
		"userId":       userID.String(),
		"roles":        roles,
	}
	if activeRole != nil {
		resp["activeRole"] = *activeRole
	} else {
		resp["activeRole"] = ""
	}
	a.recordAudit(ctx, &userID, "", "sign_in", "user", userID.String(), true, nil)
	writeData(w, http.StatusOK, resp)
}

type selectRoleReq struct {
	Role string `json:"role"`
}

func (a *App) handleSelectActiveRole(w http.ResponseWriter, r *http.Request) {
	cu, ok := a.requireAuth(w, r)
	if !ok {
		return
	}
	var req selectRoleReq
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, errInvalidJSON)
		return
	}
	if req.Role == "" {
		writeErr(w, newErr(http.StatusBadRequest, "invalid_role", "role is required"))
		return
	}
	if !hasRole(cu, req.Role) {
		writeErr(w, newErr(http.StatusForbidden, "role_not_held", "the account does not hold this role"))
		return
	}
	_, err := a.DB.Exec(r.Context(), `UPDATE sessions SET active_role=$1 WHERE token=$2`, req.Role, cu.SessionToken)
	if err != nil {
		writeErr(w, errInternal)
		return
	}
	a.recordAudit(r.Context(), &cu.ID, req.Role, "select_active_role", "user", cu.ID.String(), true, nil)
	writeData(w, http.StatusOK, map[string]interface{}{"activeRole": req.Role, "roles": cu.Roles})
}

func (a *App) handleReadUiBootstrap(w http.ResponseWriter, r *http.Request) {
	cu, ok := a.requireAuth(w, r)
	if !ok {
		return
	}
	user := map[string]interface{}{
		"userId":                 cu.ID.String(),
		"username":               cu.Username,
		"fullName":               cu.FullName,
		"roles":                  cu.Roles,
		"activeRole":             cu.ActiveRole,
		"roleSelectionRequired":  cu.ActiveRole == "",
	}
	data := map[string]interface{}{
		"user":       user,
		"serverTime": time.Now().UTC().Format(rfc3339),
	}
	if cu.ActiveRole == "requester" {
		samples, _ := a.listRequesterSamples(r.Context(), cu.ID)
		data["requesterSamples"] = samples
	}
	if isAdminOrDispatcher(cu.ActiveRole) {
		ops, err := a.buildOperationsState(r.Context())
		if err == nil {
			data["operations"] = ops
		}
	}
	writeData(w, http.StatusOK, data)
}

type createUserReq struct {
	Username         string          `json:"username"`
	InitialPassword  string          `json:"initialPassword"`
	Email            string          `json:"email"`
	FullName         string          `json:"fullName"`
	Phone            string          `json:"phone"`
	Roles            []string        `json:"roles"`
	Qualifications   []string        `json:"qualifications"`
	Certifications   []certReq       `json:"certifications"`
	Active           bool            `json:"active"`
	AssignedLocation *uuid.UUID      `json:"assignedLocationId"`
}

type certReq struct {
	Code      string  `json:"code"`
	Active    bool    `json:"active"`
	ExpiresAt *string `json:"expiresAt"`
}

func (a *App) handleCreateUser(w http.ResponseWriter, r *http.Request) {
	cu, ok := a.requireAuth(w, r)
	if !ok {
		return
	}
	if !requireActiveRole(w, cu, "administrator") {
		return
	}
	body, _ := io.ReadAll(r.Body)
	var req createUserReq
	if err := json.Unmarshal(body, &req); err != nil {
		writeErr(w, errInvalidJSON)
		return
	}
	if req.Username == "" || req.InitialPassword == "" || len(req.Roles) == 0 {
		writeErr(w, newErr(http.StatusBadRequest, "invalid_user", "username, initialPassword and roles are required"))
		return
	}
	ctx := r.Context()

	var exists bool
	_ = a.DB.QueryRow(ctx, `SELECT EXISTS(SELECT 1 FROM users WHERE username=$1)`, req.Username).Scan(&exists)
	if exists {
		writeErr(w, newErr(http.StatusConflict, "username_exists", "username already exists"))
		return
	}

	hash, err := hashPassword(req.InitialPassword)
	if err != nil {
		writeErr(w, errInternal)
		return
	}
	var id uuid.UUID
	err = a.DB.QueryRow(ctx, `INSERT INTO users (username, password_hash, email, full_name, phone, active, assigned_location_id)
		VALUES ($1,$2,$3,$4,$5,$6,$7) RETURNING id`, req.Username, hash, req.Email, req.FullName, req.Phone, req.Active, req.AssignedLocation).Scan(&id)
	if err != nil {
		writeErr(w, errInternal)
		return
	}
	for _, role := range req.Roles {
		_, _ = a.DB.Exec(ctx, `INSERT INTO user_roles (user_id, role) VALUES ($1,$2)`, id, role)
	}
	for _, q := range req.Qualifications {
		_, _ = a.DB.Exec(ctx, `INSERT INTO user_qualifications (user_id, qualification) VALUES ($1,$2)`, id, q)
	}
	for _, c := range req.Certifications {
		var expiresAt *time.Time
		if c.ExpiresAt != nil {
			if t, err := parseTime(*c.ExpiresAt); err == nil {
				expiresAt = &t
			}
		}
		_, _ = a.DB.Exec(ctx, `INSERT INTO user_certifications (user_id, code, active, expires_at) VALUES ($1,$2,$3,$4)`, id, c.Code, c.Active, expiresAt)
	}
	_, _ = a.DB.Exec(ctx, `INSERT INTO worker_availability (worker_id, available, capacity_units) VALUES ($1, TRUE, 1) ON CONFLICT DO NOTHING`, id)

	a.recordAudit(ctx, &cu.ID, cu.ActiveRole, "create_user", "user", id.String(), true, map[string]interface{}{"roles": req.Roles})
	resp := a.userToResponse(ctx, id)
	writeData(w, http.StatusCreated, resp)
}

func (a *App) userToResponse(ctx context.CtxLike, id uuid.UUID) map[string]interface{} {
	return nil
}
"}

