{"command":"create","path":"/workspace/backend/cmd/server/seed.go","file_text":"package main

import "context"

type defaultType struct {
	name           string
	container      string
	tMin, tMax     float64
	requiresCooled bool
	timeCritical   bool
	qualification  string
}

// ensureDefaultSampleTypes seeds the four named sample types required by the
// spec if they do not already exist. Safe to call on every startup.
func (a *App) ensureDefaultSampleTypes(ctx context.Context) error {
	defaults := []defaultType{
		{"Amber", "standard_tube", 2, 8, false, false, "amber_collector"},
		{"Indigo", "standard_tube", 2, 8, false, false, "indigo_collector"},
		{"Frost", "cooled_tube", -20, -4, true, false, "frost_collector"},
		{"Pulse", "standard_tube", 2, 8, false, true, "pulse_collector"},
	}
	for _, d := range defaults {
		var exists bool
		if err := a.DB.QueryRow(ctx, `SELECT EXISTS(SELECT 1 FROM sample_types WHERE name=$1)`, d.name).Scan(&exists); err != nil {
			return err
		}
		if exists {
			continue
		}
		_, err := a.DB.Exec(ctx, `INSERT INTO sample_types
			(name, container_type, temperature_min_c, temperature_max_c, requires_qualified_collector, required_qualification, requires_cooled, time_critical)
			VALUES ($1,$2,$3,$4,TRUE,$5,$6,$7)`,
			d.name, d.container, d.tMin, d.tMax, d.qualification, d.requiresCooled, d.timeCritical)
		if err != nil {
			return err
		}
	}
	// Indigo must not share a container with Amber.
	var amberID, indigoID string
	_ = a.DB.QueryRow(ctx, `SELECT id::text FROM sample_types WHERE name='Amber'`).Scan(&amberID)
	_ = a.DB.QueryRow(ctx, `SELECT id::text FROM sample_types WHERE name='Indigo'`).Scan(&indigoID)
	if amberID != "" && indigoID != "" {
		_, _ = a.DB.Exec(ctx, `UPDATE sample_types SET incompatible_with = array(SELECT DISTINCT unnest(incompatible_with || $2::uuid)) WHERE id = $1::uuid`, amberID, indigoID)
		_, _ = a.DB.Exec(ctx, `UPDATE sample_types SET incompatible_with = array(SELECT DISTINCT unnest(incompatible_with || $2::uuid)) WHERE id = $1::uuid`, indigoID, amberID)
	}
	return nil
}
"}

