type configureCapacityReq struct {
	ResourceID          uuid.UUID `json:"resourceId"`
	CapacityUnits       int       `json:"capacityUnits"`
	CooledCapacityUnits *int      `json:"cooledCapacityUnits"`
}

func (a *App) handleConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	cu, ok := a.requireAuth(w, r)
	if !ok {
		return
	}
	var req configureCapacityReq
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, errInvalidJSON)
		return
	}
	cooled := 0
	if req.CooledCapacityUnits != nil {
		cooled = *req.CooledCapacityUnits
	}
	ctx := r.Context()

	// Determine resource kind and enforce role-based scoping.
	var isLocation bool
	_ = a.DB.QueryRow(ctx, `SELECT EXISTS(SELECT 1 FROM locations WHERE id=$1)`, req.ResourceID).Scan(&isLocation)
	if isLocation {
		if cu.ActiveRole == "node_handler" || cu.ActiveRole == "laboratory_team" {
			if cu.AssignedLoc == nil || *cu.AssignedLoc != req.ResourceID {
				writeErr(w, errForbidden)
				return
			}
		} else if !requireActiveRole(w, cu, "administrator", "dispatcher") {
			return
		}
		tag, err := a.DB.Exec(ctx, `UPDATE locations SET capacity_units=$1, cooled_capacity_units=$2 WHERE id=$3`, req.CapacityUnits, cooled, req.ResourceID)
		if err != nil || tag.RowsAffected() == 0 {
			writeErr(w, errNotFound)
			return
		}
	} else {
		if !requireActiveRole(w, cu, "administrator", "dispatcher") {
			return
		}
		tag, err := a.DB.Exec(ctx, `UPDATE connections SET capacity_units=$1, cooled_capacity_units=$2 WHERE id=$3`, req.CapacityUnits, cooled, req.ResourceID)
		if err != nil || tag.RowsAffected() == 0 {
			writeErr(w, errNotFound)
			return
		}
	}
	a.bumpNetworkRevision(ctx)
	a.recordAudit(ctx, &cu.ID, cu.ActiveRole, "configure_capacity", "capacity_resource", req.ResourceID.String(), true, map[string]interface{}{"capacityUnits": req.CapacityUnits, "cooledCapacityUnits": cooled})
	writeData(w, http.StatusOK, map[string]interface{}{
		"resourceId": req.ResourceID.String(), "capacityUnits": req.CapacityUnits, "cooledCapacityUnits": cooled,
	})
}

