{"command":"create","path":"/workspace/backend/cmd/server/serviceability.go","file_text":"package main

import (
	"container/heap"
	"context"
	"net/http"
	"time"

	"github.com/google/uuid"
)

type netLocation struct {
	ID                 uuid.UUID
	Name               string
	Lat, Lon           float64
	CoverageKm         float64
	HandlingMinutes    int
	Active             bool
	IsCollectionPoint  bool
	IsTransferPoint    bool
	IsHub              bool
	IsLaboratory       bool
	CapacityAvailable  int
	CooledAvailable    int
	AcceptedTypes      map[uuid.UUID]bool
}

type netConnection struct {
	ID                uuid.UUID
	From, To          uuid.UUID
	TravelMinutes     int
	Cooled            bool
	Active            bool
	CapacityAvailable int
	CooledAvailable   int
}

type sampleTypeInfo struct {
	ID             uuid.UUID
	RequiresCooled bool
	TimeCritical   bool
	ContainerType  string
	TempMin, TempMax float64
	Incompatible   []uuid.UUID
	RequiredQual   string
}

func (a *App) loadSampleType(ctx context.Context, id uuid.UUID) (*sampleTypeInfo, error) {
	st := &sampleTypeInfo{ID: id}
	err := a.DB.QueryRow(ctx, `SELECT requires_cooled, time_critical, container_type, temperature_min_c, temperature_max_c,
		incompatible_with, coalesce(required_qualification,'') FROM sample_types WHERE id=$1`, id).
		Scan(&st.RequiresCooled, &st.TimeCritical, &st.ContainerType, &st.TempMin, &st.TempMax, &st.Incompatible, &st.RequiredQual)
	if err != nil {
		return nil, err
	}
	return st, nil
}

func (a *App) loadNetwork(ctx context.Context) (map[uuid.UUID]*netLocation, []*netConnection, error) {
	locs := make(map[uuid.UUID]*netLocation)
	rows, err := a.DB.Query(ctx, `SELECT id, name, latitude, longitude, coverage_km, handling_minutes, active,
		is_collection_point, is_transfer_point, is_hub, is_laboratory,
		capacity_units - capacity_reserved, cooled_capacity_units - cooled_capacity_reserved FROM locations`)
	if err != nil {
		return nil, nil, err
	}
	for rows.Next() {
		l := &netLocation{AcceptedTypes: map[uuid.UUID]bool{}}
		if err := rows.Scan(&l.ID, &l.Name, &l.Lat, &l.Lon, &l.CoverageKm, &l.HandlingMinutes, &l.Active,
			&l.IsCollectionPoint, &l.IsTransferPoint, &l.IsHub, &l.IsLaboratory, &l.CapacityAvailable, &l.CooledAvailable); err != nil {
			rows.Close()
			return nil, nil, err
		}
		locs[l.ID] = l
	}
	rows.Close()

	accRows, err := a.DB.Query(ctx, `SELECT location_id, sample_type_id FROM laboratory_accepted_sample_types`)
	if err == nil {
		for accRows.Next() {
			var lid, sid uuid.UUID
			_ = accRows.Scan(&lid, &sid)
			if l, ok := locs[lid]; ok {
				l.AcceptedTypes[sid] = true
			}
		}
		accRows.Close()
	}

	var conns []*netConnection
	crows, err := a.DB.Query(ctx, `SELECT id, from_location_id, to_location_id, travel_minutes, cooled, active,
		capacity_units - capacity_reserved, cooled_capacity_units - cooled_capacity_reserved FROM connections`)
	if err != nil {
		return nil, nil, err
	}
	for crows.Next() {
		c := &netConnection{}
		if err := crows.Scan(&c.ID, &c.From, &c.To, &c.TravelMinutes, &c.Cooled, &c.Active, &c.CapacityAvailable, &c.CooledAvailable); err != nil {
			crows.Close()
			return nil, nil, err
		}
		conns = append(conns, c)
	}
	crows.Close()
	return locs, conns, nil
}

// nearestCollectionPoint finds the closest active collection-point location
// within its configured coverage radius of the given coordinate.
func nearestCollectionPoint(locs map[uuid.UUID]*netLocation, lat, lon float64) *netLocation {
	var best *netLocation
	bestDist := 1e18
	for _, l := range locs {
		if !l.Active || !l.IsCollectionPoint {
			continue
		}
		d := haversineKm(lat, lon, l.Lat, l.Lon)
		if d <= l.CoverageKm && d < bestDist {
			bestDist = d
			best = l
		}
	}
	return best
}

type pqItem struct {
	loc      uuid.UUID
	priority int
}
type priorityQueue []*pqItem

func (pq priorityQueue) Len() int            { return len(pq) }
func (pq priorityQueue) Less(i, j int) bool  { return pq[i].priority < pq[j].priority }
func (pq priorityQueue) Swap(i, j int)       { pq[i], pq[j] = pq[j], pq[i] }
func (pq *priorityQueue) Push(x interface{}) { *pq = append(*pq, x.(*pqItem)) }
func (pq *priorityQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	item := old[n-1]
	*pq = old[:n-1]
	return item
}

type routeStep struct {
	Connection *netConnection
}

// shortestRoute performs Dijkstra over active connections satisfying the
// cooled requirement and capacity availability, returning the ordered list of
// connections from start to any location satisfying isDestination, and the
// total travel minutes (including per-node handling minutes along the way).
func shortestRoute(locs map[uuid.UUID]*netLocation, conns []*netConnection, start uuid.UUID, needsCooled bool, isDestination func(*netLocation) bool) ([]*netConnection, int, uuid.UUID, bool) {
	adj := make(map[uuid.UUID][]*netConnection)
	for _, c := range conns {
		if !c.Active {
			continue
		}
		if c.CapacityAvailable <= 0 {
			continue
		}
		if needsCooled && (!c.Cooled || c.CooledAvailable <= 0) {
			continue
		}
		adj[c.From] = append(adj[c.From], c)
	}

	dist := map[uuid.UUID]int{start: 0}
	prevConn := map[uuid.UUID]*netConnection{}
	pq := &priorityQueue{{loc: start, priority: 0}}
	visited := map[uuid.UUID]bool{}

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*pqItem)
		u := item.loc
		if visited[u] {
			continue
		}
		visited[u] = true

		if loc, ok := locs[u]; ok && loc.Active && isDestination(loc) && u != start {
			// Reconstruct path.
			var path []*netConnection
			cur := u
			for cur != start {
				c := prevConn[cur]
				if c == nil {
					break
				}
				path = append([]*netConnection{c}, path...)
				cur = c.From
			}
			return path, dist[u], u, true
		}

		for _, c := range adj[u] {
			toLoc, ok := locs[c.To]
			if !ok || !toLoc.Active {
				continue
			}
			nd := dist[u] + c.TravelMinutes + toLoc.HandlingMinutes
			if existing, ok := dist[c.To]; !ok || nd < existing {
				dist[c.To] = nd
				prevConn[c.To] = c
				heap.Push(pq, &pqItem{loc: c.To, priority: nd})
			}
		}
	}
	return nil, 0, uuid.Nil, false
}

func init() {
	heap.Init(&priorityQueue{})
}

// ---------------- HTTP handlers ----------------

type checkServiceabilityReq struct {
	Origin                coordDTO   `json:"origin"`
	OriginType            string     `json:"originType"`
	OriginNodeID          *uuid.UUID `json:"originNodeId"`
	SampleTypeID          uuid.UUID  `json:"sampleTypeId"`
	RequestedAt           string     `json:"requestedAt"`
	DeliveryDeadline      string     `json:"deliveryDeadline"`
	EarliestCollectionAt  *string    `json:"earliestCollectionAt"`
	LatestCollectionAt    *string    `json:"latestCollectionAt"`
}

func (a *App) handleCheckServiceability(w http.ResponseWriter, r *http.Request) {
	cu, ok := a.requireAuth(w, r)
	if !ok {
		return
	}
	if !requireActiveRole(w, cu, "requester", "administrator", "dispatcher") {
		return
	}
	var req checkServiceabilityReq
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, errInvalidJSON)
		return
	}
	deadline, err := parseTime(req.DeliveryDeadline)
	if err != nil {
		writeErr(w, newErr(http.StatusBadRequest, "invalid_deadline", "deliveryDeadline must be RFC3339"))
		return
	}
	requestedAt, err := parseTime(req.RequestedAt)
	if err != nil {
		writeErr(w, newErr(http.StatusBadRequest, "invalid_requested_at", "requestedAt must be RFC3339"))
		return
	}

	ctx := r.Context()
	st, err := a.loadSampleType(ctx, req.SampleTypeID)
	if err != nil {
		writeErr(w, newErr(http.StatusBadRequest, "invalid_sample_type", "unknown sampleTypeId"))
		return
	}

	result := a.computeServiceability(ctx, req.Origin.Latitude, req.Origin.Longitude, st, requestedAt, deadline)

	version, _ := a.currentServiceabilityVersion(ctx)
	data := map[string]interface{}{
		"serviceable":            result.serviceable,
		"reason":                 result.reason,
		"serviceabilityVersion":  version,
	}
	if result.serviceable {
		data["targetLaboratoryId"] = result.labID.String()
		data["estimatedArrivalAt"] = result.eta.UTC().Format(rfc3339)
	}
	a.recordAudit(ctx, &cu.ID, cu.ActiveRole, "check_serviceability", "serviceability", "", true, map[string]interface{}{"serviceable": result.serviceable, "reason": result.reason})
	writeData(w, http.StatusOK, data)
}

type serviceabilityResult struct {
	serviceable bool
	reason      string
	labID       uuid.UUID
	eta         time.Time
}

// computeServiceability implements the serviceability rules independent of
// any specific worker or vehicle availability, per the pinned business rules.
func (a *App) computeServiceability(ctx context.Context, lat, lon float64, st *sampleTypeInfo, requestedAt, deadline time.Time) serviceabilityResult {
	locs, conns, err := a.loadNetwork(ctx)
	if err != nil {
		return serviceabilityResult{reason: "no_route"}
	}

	cp := nearestCollectionPoint(locs, lat, lon)
	if cp == nil {
		return serviceabilityResult{reason: "outside_service_coverage"}
	}

	anyLabAcceptsType := false
	for _, l := range locs {
		if l.Active && l.IsLaboratory && l.AcceptedTypes[st.ID] {
			anyLabAcceptsType = true
			break
		}
	}
	if !anyLabAcceptsType {
		return serviceabilityResult{reason: "no_accepting_laboratory"}
	}

	isDest := func(l *netLocation) bool { return l.IsLaboratory && l.AcceptedTypes[st.ID] }
	path, minutes, destID, found := shortestRoute(locs, conns, cp.ID, st.RequiresCooled, isDest)

	// Direct case: origin's nearest collection point is itself a laboratory accepting the type.
	if !found {
		if isDest(cp) {
			path = nil
			minutes = cp.HandlingMinutes
			destID = cp.ID
			found = true
		}
	}
	if !found {
		return serviceabilityResult{reason: "no_route"}
	}

	// Capacity check along the path plus destination lab, and the initial collection point.
	if st.RequiresCooled {
		if cp.CooledAvailable <= 0 {
			return serviceabilityResult{reason: "insufficient_capacity"}
		}
	} else if cp.CapacityAvailable <= 0 {
		return serviceabilityResult{reason: "insufficient_capacity"}
	}
	for _, c := range path {
		if st.RequiresCooled && c.CooledAvailable <= 0 {
			return serviceabilityResult{reason: "insufficient_capacity"}
		}
		if !st.RequiresCooled && c.CapacityAvailable <= 0 {
			return serviceabilityResult{reason: "insufficient_capacity"}
		}
	}
	destLoc := locs[destID]
	if st.RequiresCooled && destLoc.CooledAvailable <= 0 {
		return serviceabilityResult{reason: "insufficient_capacity"}
	}
	if !st.RequiresCooled && destLoc.CapacityAvailable <= 0 {
		return serviceabilityResult{reason: "insufficient_capacity"}
	}

	eta := requestedAt.Add(time.Duration(minutes+cp.HandlingMinutes) * time.Minute)
	if eta.After(deadline) {
		return serviceabilityResult{reason: "deadline_unreachable"}
	}

	return serviceabilityResult{serviceable: true, reason: "serviceable", labID: destID, eta: eta}
}

func (a *App) currentServiceabilityVersion(ctx context.Context) (int, error) {
	var version int
	err := a.DB.QueryRow(ctx, `SELECT version FROM current_serviceability_version WHERE id=TRUE`).Scan(&version)
	if err != nil {
		return a.recomputeServiceabilitySnapshot(ctx)
	}
	if version == 0 {
		return a.recomputeServiceabilitySnapshot(ctx)
	}
	var networkRev, curRev int
	_ = a.DB.QueryRow(ctx, `SELECT network_revision FROM serviceability_snapshots WHERE version=$1`, version).Scan(&networkRev)
	_ = a.DB.QueryRow(ctx, `SELECT revision FROM network_revision WHERE id=TRUE`).Scan(&curRev)
	if networkRev != curRev {
		return a.recomputeServiceabilitySnapshot(ctx)
	}
	return version, nil
}

// recomputeServiceabilitySnapshot computes and publishes a brand-new,
// complete serviceability-calculation version atomically: the previous
// version remains readable until this one is fully written and the pointer
// is flipped.
func (a *App) recomputeServiceabilitySnapshot(ctx context.Context) (int, error) {
	locs, _, err := a.loadNetwork(ctx)
	if err != nil {
		return 0, err
	}
	var regions []map[string]interface{}
	count := 0
	for _, l := range locs {
		if l.Active && l.IsCollectionPoint {
			count++
			regions = append(regions, map[string]interface{}{
				"locationId": l.ID.String(), "name": l.Name, "latitude": l.Lat, "longitude": l.Lon, "coverageKm": l.CoverageKm,
			})
		}
	}
	var curRev int
	_ = a.DB.QueryRow(ctx, `SELECT revision FROM network_revision WHERE id=TRUE`).Scan(&curRev)

	var nextVersion int
	_ = a.DB.QueryRow(ctx, `SELECT coalesce(max(version),0)+1 FROM serviceability_snapshots`).Scan(&nextVersion)

	regionsJSON := mustJSON(regions)
	_, err = a.DB.Exec(ctx, `INSERT INTO serviceability_snapshots (version, status, network_revision, regions, active_collection_point_count)
		VALUES ($1,'complete',$2,$3,$4)`, nextVersion, curRev, regionsJSON, count)
	if err != nil {
		return 0, err
	}
	// Atomically publish the new version pointer only once fully written above.
	_, err = a.DB.Exec(ctx, `INSERT INTO current_serviceability_version (id, version) VALUES (TRUE, $1)
		ON CONFLICT (id) DO UPDATE SET version=$1`, nextVersion)
	if err != nil {
		return 0, err
	}
	return nextVersion, nil
}

func (a *App) handleReadServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	cu, ok := a.requireAuth(w, r)
	if !ok {
		return
	}
	if cu.ActiveRole == "" {
		writeErr(w, errRoleNotSel)
		return
	}
	ctx := r.Context()
	version, err := a.currentServiceabilityVersion(ctx)
	if err != nil {
		writeErr(w, errInternal)
		return
	}
	var status string
	var computedAt time.Time
	var networkRev, count int
	var regionsRaw []byte
	err = a.DB.QueryRow(ctx, `SELECT status, computed_at, network_revision, regions, active_collection_point_count
		FROM serviceability_snapshots WHERE version=$1`, version).Scan(&status, &computedAt, &networkRev, &regionsRaw, &count)
	if err != nil {
		writeErr(w, errInternal)
		return
	}
	var regions []map[string]interface{}
	_ = jsonUnmarshal(regionsRaw, &regions)
	writeData(w, http.StatusOK, map[string]interface{}{
		"version":                    version,
		"status":                     status,
		"computedAt":                 computedAt.UTC().Format(rfc3339),
		"networkRevision":            networkRev,
		"regions":                    regions,
		"activeCollectionPointCount": count,
	})
}
"}

