// declineAndReoffer records the decline, tracks the decliner for temporary
// priority reduction (never permanent exclusion), and offers the assignment
// to the next eligible worker.
func (a *App) declineAndReoffer(ctx interface {
	Deadline() (time.Time, bool)
	Done() <-chan struct{}
	Err() error
	Value(key interface{}) interface{}
}, assignmentID, workerID uuid.UUID, reason, role string) {
	_, _ = a.DB.Exec(ctx, `UPDATE assignments SET status='unassigned', offered_worker_id=NULL, offer_expires_at=NULL,
		tried_worker_ids = array_append(tried_worker_ids, $1) WHERE id=$2`, workerID, assignmentID)
	_, _ = a.DB.Exec(ctx, `UPDATE worker_availability SET decline_count = decline_count + 1,
		penalized_until = now() + interval '30 minutes' WHERE worker_id=$1`, workerID)
	a.recordTimeline(ctx, "assignment", assignmentID, "declined", &workerID, role, true, map[string]interface{}{"reason": reason})
	a.recordAudit(ctx, &workerID, role, "decline_assignment", "assignment", assignmentID.String(), true, map[string]interface{}{"reason": reason})
	a.offerAssignment(ctx, assignmentID)
}

