	var acceptedWorker *uuid.UUID
	var kind, sampleTypeID string
	err := a.DB.QueryRow(ctx, `SELECT accepted_worker_id, kind FROM assignments WHERE id=$1 AND sample_id=$2`, req.AssignmentID, req.SampleID).
		Scan(&acceptedWorker, &kind)
	if err != nil || kind != "collection" {
		writeErr(w, errNotFound)
		return
	}
	if acceptedWorker == nil || *acceptedWorker != cu.ID {
		writeErr(w, errForbidden)
