	_ = a.DB.QueryRow(ctx, `SELECT st.temperature_min_c, st.temperature_max_c, st.container_type FROM samples s
		JOIN sample_types st ON st.id = s.sample_type_id WHERE s.id=$1`, req.SampleID).Scan(&tMin, &tMax, &requiredContainer)
	sampleTypeID = ""
	_ = sampleTypeID

	withinRange := req.ObservedTemperatureC >= tMin && req.ObservedTemperatureC <= tMax && req.ContainerType == requiredContainer

	collectedAt, err := parseTime(req.CollectedAt)
	if err != nil {
		writeErr(w, newErr(http.StatusBadRequest, "invalid_collected_at", "collectedAt must be RFC3339"))
