		return
	}
	_, _ = a.DB.Exec(ctx, `UPDATE assignments SET status='completed', updated_at=now() WHERE id=$1`, req.AssignmentID)
	_, _ = a.DB.Exec(ctx, `INSERT INTO sample_completed_legs (sample_id, assignment_id) VALUES ($1,$2) ON CONFLICT DO NOTHING`, req.SampleID, req.AssignmentID)
	_, _ = a.DB.Exec(ctx, `INSERT INTO handling_checkpoints (sample_id, recorded_by, container_type, temperature_c, within_range, recorded_at)
		VALUES ($1,$2,$3,$4,$5,$6)`, req.SampleID, cu.ID, req.ContainerType, req.ObservedTemperatureC, withinRange, collectedAt)

	if !withinRange {
		_, _ = a.DB.Exec(ctx, `UPDATE samples SET exception_reason='handling_out_of_range' WHERE id=$1`, req.SampleID)
		_, _ = a.DB.Exec(ctx, `INSERT INTO exceptions (sample_id, assignment_id, reason, details) VALUES ($1,$2,'handling_out_of_range','{}')`, req.SampleID, req.AssignmentID)
	}

	a.recordTimeline(ctx, "sample", req.SampleID, "collected_and_sealed", &cu.ID, cu.ActiveRole, true, map[string]interface{}{
		"containerType": req.ContainerType, "observedTemperatureC": req.ObservedTemperatureC, "withinRange": withinRange,
	})
	a.recordAudit(ctx, &cu.ID, cu.ActiveRole, "collect_and_seal_sample", "sample", req.SampleID.String(), true, map[string]interface{}{"withinRange": withinRange})

	// Kick off the next assignment in the journey (if any).
	var journeyID *uuid.UUID
	_ = a.DB.QueryRow(ctx, `SELECT active_journey_id FROM samples WHERE id=$1`, req.SampleID).Scan(&journeyID)
	if journeyID != nil {
		a.offerFirstPendingAssignment(ctx, *journeyID)
	}
	a.emit(ctx, "sample_collected", "sample", req.SampleID.String(), "dispatcher", nil, map[string]interface{}{"sampleId": req.SampleID.String()})

	resp := map[string]interface{}{"sampleId": req.SampleID.String(), "sealed": true, "status": newStatus, "withinRange": withinRange}
	a.saveIdempotency(ctx, req.IdempotencyKey, "collect-and-seal-sample", cu.ID, body, http.StatusOK, map[string]interface{}{"data": resp})
	writeData(w, http.StatusOK, resp)
}

type initiateHandoffReq struct {
	SampleID         uuid.UUID `json:"sampleId"`
	FromAssignmentID uuid.UUID `json:"fromAssignmentId"`
	ToAssignmentID   uuid.UUID `json:"toAssignmentId"`
	ReceiverID       uuid.UUID `json:"receiverId"`
	InitiatedAt      string    `json:"initiatedAt"`
	IdempotencyKey   string    `json:"idempotencyKey"`
}

func (a *App) handleInitiateHandoff(w http.ResponseWriter, r *http.Request) {
	cu, ok := a.requireAuth(w, r)
	if !ok {
		return
	}
	body, _ := io.ReadAll(r.Body)
	var req initiateHandoffReq
	if err := jsonUnmarshal(body, &req); err != nil {
		writeErr(w, errInvalidJSON)
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, errIdemRequired)
		return
	}
	ctx := r.Context()
	if status, resp, cached, conflict := a.checkIdempotency(ctx, req.IdempotencyKey, "initiate-handoff", cu.ID, body); cached {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(status)
		_, _ = w.Write(resp)
		return
	} else if conflict {
		writeErr(w, newErr(http.StatusConflict, "idempotency_conflict", "idempotencyKey reused with a different request"))
		return
	}

	var currentHolder *uuid.UUID
	err := a.DB.QueryRow(ctx, `SELECT current_holder_id FROM samples WHERE id=$1`, req.SampleID).Scan(&currentHolder)
	if err != nil {
		writeErr(w, errNotFound)
		return
	}
	if currentHolder == nil || *currentHolder != cu.ID {
		writeErr(w, errForbidden)
		return
	}
	var fromLoc, toLoc *uuid.UUID
	_ = a.DB.QueryRow(ctx, `SELECT to_location_id FROM assignments WHERE id=$1`, req.FromAssignmentID).Scan(&fromLoc)
	_ = a.DB.QueryRow(ctx, `SELECT from_location_id FROM assignments WHERE id=$1`, req.ToAssignmentID).Scan(&toLoc)

	// Idempotent: reuse any existing pending handoff for this sample+pair.
	var handoffID uuid.UUID
	err = a.DB.QueryRow(ctx, `SELECT id FROM handoffs WHERE sample_id=$1 AND assignment_id=$2 AND status='pending'`, req.SampleID, req.FromAssignmentID).Scan(&handoffID)
	if err != nil {
		err = a.DB.QueryRow(ctx, `INSERT INTO handoffs (sample_id, assignment_id, from_holder_id, to_holder_id, from_location_id, to_location_id, status)
			VALUES ($1,$2,$3,$4,$5,$6,'pending') RETURNING id`, req.SampleID, req.FromAssignmentID, cu.ID, req.ReceiverID, fromLoc, toLoc).Scan(&handoffID)
		if err != nil {
			writeErr(w, errInternal)
			return
		}
	}
	_, _ = a.DB.Exec(ctx, `UPDATE samples SET status='in_handoff' WHERE id=$1`, req.SampleID)
	a.recordTimeline(ctx, "sample", req.SampleID, "handoff_initiated", &cu.ID, cu.ActiveRole, true, map[string]interface{}{"handoffId": handoffID.String(), "receiverId": req.ReceiverID.String()})
	a.recordAudit(ctx, &cu.ID, cu.ActiveRole, "initiate_handoff", "handoff", handoffID.String(), true, nil)
	a.emit(ctx, "handoff_initiated", "handoff", handoffID.String(), "", &req.ReceiverID, map[string]interface{}{"handoffId": handoffID.String(), "sampleId": req.SampleID.String()})

	resp := map[string]interface{}{"handoffId": handoffID.String(), "sampleId": req.SampleID.String(), "status": "pending"}
	a.saveIdempotency(ctx, req.IdempotencyKey, "initiate-handoff", cu.ID, body, http.StatusOK, map[string]interface{}{"data": resp})
	writeData(w, http.StatusOK, resp)
}

type confirmHandoffReq struct {
	HandoffID        uuid.UUID `json:"handoffId"`
	ConfirmationSide string    `json:"confirmationSide"`
	ConfirmedAt      string    `json:"confirmedAt"`
	IdempotencyKey   string    `json:"idempotencyKey"`
}

func (a *App) handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	cu, ok := a.requireAuth(w, r)
	if !ok {
		return
	}
	body, _ := io.ReadAll(r.Body)
	var req confirmHandoffReq
	if err := jsonUnmarshal(body, &req); err != nil {
		writeErr(w, errInvalidJSON)
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, errIdemRequired)
		return
	}
	ctx := r.Context()
	if status, resp, cached, conflict := a.checkIdempotency(ctx, req.IdempotencyKey, "confirm-handoff", cu.ID, body); cached {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(status)
		_, _ = w.Write(resp)
		return
	} else if conflict {
		writeErr(w, newErr(http.StatusConflict, "idempotency_conflict", "idempotencyKey reused with a different request"))
		return
	}

	var fromHolder, toHolder uuid.UUID
	var sampleID uuid.UUID
	var assignmentID *uuid.UUID
	var status string
	var senderConfirmed, receiverConfirmed bool
	err := a.DB.QueryRow(ctx, `SELECT from_holder_id, to_holder_id, sample_id, assignment_id, status, sender_confirmed, receiver_confirmed
		FROM handoffs WHERE id=$1`, req.HandoffID).Scan(&fromHolder, &toHolder, &sampleID, &assignmentID, &status, &senderConfirmed, &receiverConfirmed)
	if err != nil {
		writeErr(w, errNotFound)
		return
	}
	if status == "completed" {
		resp := map[string]interface{}{"handoffId": req.HandoffID.String(), "status": "completed"}
		writeData(w, http.StatusOK, resp)
		return
	}
	if req.ConfirmationSide == "sender" {
		if cu.ID != fromHolder {
			writeErr(w, errForbidden)
			return
		}
		senderConfirmed = true
		_, _ = a.DB.Exec(ctx, `UPDATE handoffs SET sender_confirmed=TRUE WHERE id=$1`, req.HandoffID)
	} else if req.ConfirmationSide == "receiver" {
		if cu.ID != toHolder {
			writeErr(w, errForbidden)
			return
		}
		receiverConfirmed = true
		_, _ = a.DB.Exec(ctx, `UPDATE handoffs SET receiver_confirmed=TRUE WHERE id=$1`, req.HandoffID)
	} else {
		writeErr(w, newErr(http.StatusBadRequest, "invalid_side", "confirmationSide must be sender or receiver"))
		return
	}

	completed := senderConfirmed && receiverConfirmed
	if completed {
		_, err = a.DB.Exec(ctx, `UPDATE handoffs SET status='completed', completed_at=now() WHERE id=$1 AND status='pending'`, req.HandoffID)
		if err == nil {
			_, _ = a.DB.Exec(ctx, `UPDATE samples SET current_holder_id=$1, current_holder_kind='worker', status='in_transit', updated_at=now() WHERE id=$2`, toHolder, sampleID)
			if assignmentID != nil {
				_, _ = a.DB.Exec(ctx, `UPDATE assignments SET status='completed', updated_at=now() WHERE id=$1`, *assignmentID)
				_, _ = a.DB.Exec(ctx, `INSERT INTO sample_completed_legs (sample_id, assignment_id) VALUES ($1,$2) ON CONFLICT DO NOTHING`, sampleID, *assignmentID)
			}
			a.recordTimeline(ctx, "sample", sampleID, "handoff_completed", &cu.ID, cu.ActiveRole, true, map[string]interface{}{"handoffId": req.HandoffID.String(), "newHolder": toHolder.String()})
			var journeyID *uuid.UUID
			_ = a.DB.QueryRow(ctx, `SELECT active_journey_id FROM samples WHERE id=$1`, sampleID).Scan(&journeyID)
			if journeyID != nil {
				a.offerFirstPendingAssignment(ctx, *journeyID)
			}
			a.emit(ctx, "handoff_completed", "handoff", req.HandoffID.String(), "dispatcher", nil, map[string]interface{}{"handoffId": req.HandoffID.String(), "sampleId": sampleID.String()})
		}
	}

	a.recordAudit(ctx, &cu.ID, cu.ActiveRole, "confirm_handoff", "handoff", req.HandoffID.String(), true, map[string]interface{}{"side": req.ConfirmationSide})
	respStatus := "pending"
	if completed {
		respStatus = "completed"
	}
	resp := map[string]interface{}{"handoffId": req.HandoffID.String(), "status": respStatus}
	a.saveIdempotency(ctx, req.IdempotencyKey, "confirm-handoff", cu.ID, body, http.StatusOK, map[string]interface{}{"data": resp})
	writeData(w, http.StatusOK, resp)
}

