// ---------------- Sample state / lifecycle ----------------

func (a *App) sampleTimeline(ctx context.Context, sampleID uuid.UUID) []TimelineEntry {
	t, _ := a.getTimeline(ctx, "sample", sampleID)
	return t
}

func (a *App) handleReadSampleState(w http.ResponseWriter, r *http.Request, sampleIDStr string) {
	cu, ok := a.requireAuth(w, r)
	if !ok {
		return
	}
	sampleID, err := uuid.Parse(sampleIDStr)
	if err != nil {
		writeErr(w, newErr(http.StatusBadRequest, "invalid_id", "invalid sampleId"))
		return
	}
	ctx := r.Context()

	var requesterID uuid.UUID
	var requestID uuid.UUID
	var originType, status, containerType string
	var lat, lon float64
	var requestedAt, deliveryDeadline time.Time
	var sampleTypeID uuid.UUID
	var tMin, tMax float64
	var incompat []uuid.UUID
	var activeJourneyID *uuid.UUID
	var latLast, lonLast *float64
	var locRecordedAt *time.Time

	err = a.DB.QueryRow(ctx, `SELECT s.requester_id, s.request_id, s.origin_type, s.latitude, s.longitude, s.requested_at, s.delivery_deadline,
		s.sample_type_id, st.container_type, st.temperature_min_c, st.temperature_max_c, st.incompatible_with,
		s.status, s.active_journey_id, s.latitude_last, s.longitude_last, s.location_recorded_at
		FROM samples s JOIN sample_types st ON st.id=s.sample_type_id WHERE s.id=$1`, sampleID).
		Scan(&requesterID, &requestID, &originType, &lat, &lon, &requestedAt, &deliveryDeadline,
			&sampleTypeID, &containerType, &tMin, &tMax, &incompat, &status, &activeJourneyID, &latLast, &lonLast, &locRecordedAt)
	if err != nil {
		writeErr(w, errNotFound)
		return
	}

	if cu.ActiveRole == "requester" && cu.ID != requesterID {
		writeErr(w, errForbidden)
		return
	}
	if !authorizedForSample(ctx, a, cu, sampleID, requesterID) {
		writeErr(w, errForbidden)
		return
	}

	stale := locRecordedAt == nil || time.Since(*locRecordedAt) > 15*time.Minute

	activeAssignments := a.listActiveAssignmentIDs(ctx, sampleID)

	incompatStrs := make([]string, len(incompat))
	for i, u := range incompat {
		incompatStrs[i] = u.String()
	}

	data := map[string]interface{}{
		"sampleId":               sampleID.String(),
		"requestId":              requestID.String(),
		"requesterId":            requesterID.String(),
		"origin":                 map[string]interface{}{"latitude": lat, "longitude": lon},
		"originType":             originType,
		"requestedAt":            requestedAt.UTC().Format(rfc3339),
		"deliveryDeadline":       deliveryDeadline.UTC().Format(rfc3339),
		"sampleTypeId":           sampleTypeID.String(),
		"containerType":          containerType,
		"temperatureMinC":        tMin,
		"temperatureMaxC":        tMax,
		"incompatibleSampleTypes": incompatStrs,
		"serviceability":         serviceabilityLabel(status),
		"activeAssignmentIds":    activeAssignments,
		"state":                  map[string]interface{}{"status": status},
		"timeline":               a.sampleTimeline(ctx, sampleID),
		"locationStale":          stale,
	}
	if activeJourneyID != nil {
		data["activeJourneyId"] = activeJourneyID.String()
	}
	if latLast != nil && lonLast != nil {
		data["latestLocation"] = map[string]interface{}{"latitude": *latLast, "longitude": *lonLast}
	}
	if locRecordedAt != nil {
		data["locationRecordedAt"] = locRecordedAt.UTC().Format(rfc3339)
	}
	var targetLab *uuid.UUID
	_ = a.DB.QueryRow(ctx, `SELECT target_laboratory_id FROM samples WHERE id=$1`, sampleID).Scan(&targetLab)
	if targetLab != nil {
		data["targetLaboratoryId"] = targetLab.String()
	}
	writeData(w, http.StatusOK, data)
}

func serviceabilityLabel(status string) string {
	if status == "unserviceable" {
		return "unserviceable"
	}
	return "serviceable"
}

// authorizedForSample enforces per-role visibility rules for a sample.
func authorizedForSample(ctx context.Context, a *App, cu *CurrentUser, sampleID, requesterID uuid.UUID) bool {
	switch cu.ActiveRole {
	case "administrator", "dispatcher":
		return true
	case "requester":
		return cu.ID == requesterID
	default:
		var count int
		_ = a.DB.QueryRow(ctx, `SELECT count(*) FROM assignments WHERE sample_id=$1 AND (offered_worker_id=$2 OR accepted_worker_id=$2)`, sampleID, cu.ID).Scan(&count)
		return count > 0
	}
}

func (a *App) handleReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	cu, ok := a.requireAuth(w, r)
	if !ok {
		return
	}
	var req struct {
		SampleID uuid.UUID `json:"sampleId"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, errInvalidJSON)
		return
	}
	ctx := r.Context()
	var requesterID uuid.UUID
	var status string
	var sealed bool
	var currentHolder, activeJourneyID, receivedLabID *uuid.UUID
	var latLast, lonLast *float64
	var locRecordedAt *time.Time
	var exceptionReason *string
	err := a.DB.QueryRow(ctx, `SELECT requester_id, status, sealed, current_holder_id, active_journey_id, received_laboratory_id,
		latitude_last, longitude_last, location_recorded_at, exception_reason FROM samples WHERE id=$1`, req.SampleID).
		Scan(&requesterID, &status, &sealed, &currentHolder, &activeJourneyID, &receivedLabID, &latLast, &lonLast, &locRecordedAt, &exceptionReason)
	if err != nil {
		writeErr(w, errNotFound)
		return
	}
	if !authorizedForSample(ctx, a, cu, req.SampleID, requesterID) {
		writeErr(w, errForbidden)
		return
	}
	completedLegs := []string{}
	rows, _ := a.DB.Query(ctx, `SELECT assignment_id FROM sample_completed_legs WHERE sample_id=$1`, req.SampleID)
	for rows.Next() {
		var id uuid.UUID
		_ = rows.Scan(&id)
		completedLegs = append(completedLegs, id.String())
	}
	rows.Close()

	stale := locRecordedAt == nil || time.Since(*locRecordedAt) > 15*time.Minute

	data := map[string]interface{}{
		"sampleId":                req.SampleID.String(),
		"status":                  status,
		"sealed":                  sealed,
		"completedLegIds":         completedLegs,
		"activeReplacementPlanIds": []string{},
		"timeline":                a.sampleTimeline(ctx, req.SampleID),
		"locationStale":           stale,
	}
	if activeJourneyID != nil {
		data["activeJourneyId"] = activeJourneyID.String()
	}
	if currentHolder != nil {
		data["currentHolderId"] = currentHolder.String()
	}
	if receivedLabID != nil {
		data["receivedLaboratoryId"] = receivedLabID.String()
	}
	if exceptionReason != nil {
		data["exception"] = map[string]interface{}{"reason": *exceptionReason}
	}
	var pendingHandoffID *uuid.UUID
	_ = a.DB.QueryRow(ctx, `SELECT id FROM handoffs WHERE sample_id=$1 AND status='pending' ORDER BY created_at DESC LIMIT 1`, req.SampleID).Scan(&pendingHandoffID)
	if pendingHandoffID != nil {
		data["pendingHandoffId"] = pendingHandoffID.String()
	}
	if latLast != nil && lonLast != nil {
		data["latestLocation"] = map[string]interface{}{"latitude": *latLast, "longitude": *lonLast}
	}
	if locRecordedAt != nil {
		data["locationRecordedAt"] = locRecordedAt.UTC().Format(rfc3339)
	}
	writeData(w, http.StatusOK, data)
}

