func (a *App) listRequesterSamples(ctx context.Context, requesterID uuid.UUID) ([]map[string]interface{}, error) {
	rows, err := a.DB.Query(ctx, `SELECT id, status FROM samples WHERE requester_id=$1 ORDER BY created_at DESC`, requesterID)
