func (a *App) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	cu, ok := a.requireAuth(w, r)
	if !ok {
		return
	}
	var req struct {
		Role   string `json:"role"`
		Status string `json:"status"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, errInvalidJSON)
		return
	}
	role := cu.ActiveRole
	if req.Role != "" {
		role = req.Role
	}
	if role != cu.ActiveRole {
		writeErr(w, errForbidden)
		return
	}
	ctx := r.Context()
	pending, inProgress, completed := []map[string]interface{}{}, []map[string]interface{}{}, []map[string]interface{}{}

	switch role {
	case "requester":
		rows, _ := a.DB.Query(ctx, `SELECT id, status FROM samples WHERE requester_id=$1 ORDER BY created_at DESC`, cu.ID)
		for rows.Next() {
			var id uuid.UUID
			var status string
			_ = rows.Scan(&id, &status)
			item := map[string]interface{}{"kind": "sample", "sampleId": id.String(), "status": status}
			switch status {
			case "received":
				completed = append(completed, item)
			case "awaiting_collection", "unserviceable":
				pending = append(pending, item)
			default:
				inProgress = append(inProgress, item)
			}
		}
		rows.Close()
	case "collection_professional", "delivery_partner", "node_handler", "laboratory_team":
		rows, _ := a.DB.Query(ctx, `SELECT id, kind, sample_id, status FROM assignments
			WHERE offered_worker_id=$1 OR accepted_worker_id=$1 ORDER BY created_at DESC`, cu.ID)
		for rows.Next() {
			var id, sampleID uuid.UUID
			var kind, status string
			_ = rows.Scan(&id, &kind, &sampleID, &status)
			item := map[string]interface{}{"kind": "assignment", "assignmentId": id.String(), "sampleId": sampleID.String(), "status": status, "assignmentKind": kind}
			switch status {
			case "completed", "cancelled":
				completed = append(completed, item)
			case "offered", "unassigned":
				pending = append(pending, item)
			default:
				inProgress = append(inProgress, item)
			}
		}
		rows.Close()
	case "dispatcher", "administrator":
		rows, _ := a.DB.Query(ctx, `SELECT id, status FROM journeys ORDER BY created_at DESC LIMIT 500`)
		for rows.Next() {
			var id uuid.UUID
			var status string
			_ = rows.Scan(&id, &status)
			item := map[string]interface{}{"kind": "journey", "journeyId": id.String(), "status": status}
			switch status {
			case "completed", "cancelled", "expired":
				completed = append(completed, item)
			case "planned":
				pending = append(pending, item)
			default:
				inProgress = append(inProgress, item)
			}
		}
		rows.Close()
	}

	writeData(w, http.StatusOK, map[string]interface{}{"pending": pending, "inProgress": inProgress, "completed": completed})
}

// ---------------- Operations state ----------------

func (a *App) buildOperationsState(ctx context.Context) (map[string]interface{}, error) {
	samples := []map[string]interface{}{}
	rows, err := a.DB.Query(ctx, `SELECT id, status, request_id, latitude, longitude, delivery_deadline, current_holder_id, active_journey_id,
		latitude_last, longitude_last, location_recorded_at FROM samples ORDER BY created_at DESC LIMIT 1000`)
	if err != nil {
		return nil, err
	}
	for rows.Next() {
		var id, requestID uuid.UUID
		var status string
		var lat, lon float64
		var deadline time.Time
		var holder, journeyID *uuid.UUID
		var latLast, lonLast *float64
		var recordedAt *time.Time
		_ = rows.Scan(&id, &status, &requestID, &lat, &lon, &deadline, &holder, &journeyID, &latLast, &lonLast, &recordedAt)
		stale := recordedAt == nil || time.Since(*recordedAt) > 15*time.Minute
		item := map[string]interface{}{
			"sampleId": id.String(), "status": status, "requestId": requestID.String(),
			"origin": map[string]interface{}{"latitude": lat, "longitude": lon},
			"deliveryDeadline": deadline.UTC().Format(rfc3339), "locationStale": stale,
		}
		if holder != nil {
			item["currentHolderId"] = holder.String()
		}
		if journeyID != nil {
			item["activeJourneyId"] = journeyID.String()
		}
		if latLast != nil && lonLast != nil {
			item["latestLocation"] = map[string]interface{}{"latitude": *latLast, "longitude": *lonLast}
		}
		if recordedAt != nil {
			item["locationRecordedAt"] = recordedAt.UTC().Format(rfc3339)
		}
		samples = append(samples, item)
	}
	rows.Close()

	workers := []map[string]interface{}{}
	wrows, err := a.DB.Query(ctx, `SELECT u.id, coalesce(u.full_name,''), wa.available, wa.capacity_units, wa.latitude, wa.longitude, wa.location_recorded_at,
		(SELECT count(*) FROM assignments a WHERE a.accepted_worker_id=u.id AND a.status IN ('accepted','in_progress')),
		array(SELECT role FROM user_roles ur WHERE ur.user_id=u.id)
		FROM users u JOIN worker_availability wa ON wa.worker_id=u.id WHERE u.active=TRUE`)
	if err == nil {
		for wrows.Next() {
			var id uuid.UUID
			var fullName string
			var available bool
			var capacityUnits, assignmentCount int
			var lat, lon *float64
			var recordedAt *time.Time
			var roles []string
			_ = wrows.Scan(&id, &fullName, &available, &capacityUnits, &lat, &lon, &recordedAt, &assignmentCount, &roles)
			stale := recordedAt == nil || time.Since(*recordedAt) > 15*time.Minute
			statusStr := "unavailable"
			if available {
				statusStr = "available"
			}
			w := map[string]interface{}{
				"workerId": id.String(), "fullName": fullName, "roles": roles, "available": available,
				"status": statusStr, "capacityUnits": capacityUnits, "assignmentCount": assignmentCount, "locationStale": stale,
			}
			if lat != nil && lon != nil {
				w["latestLocation"] = map[string]interface{}{"latitude": *lat, "longitude": *lon}
			}
			if recordedAt != nil {
				w["locationRecordedAt"] = recordedAt.UTC().Format(rfc3339)
			}
			workers = append(workers, w)
		}
		wrows.Close()
	}

	locations := []map[string]interface{}{}
	lrows, err := a.DB.Query(ctx, `SELECT id, name, latitude, longitude, active, coverage_km, handling_minutes,
		is_collection_point, is_transfer_point, is_hub, is_laboratory,
		capacity_units, capacity_reserved, capacity_units-capacity_reserved, cooled_capacity_units, cooled_capacity_reserved, cooled_capacity_units-cooled_capacity_reserved
		FROM locations`)
	if err == nil {
		for lrows.Next() {
			var id uuid.UUID
			var name string
			var lat, lon, coverage float64
			var active bool
			var handling int
			var isCP, isTP, isHub, isLab bool
			var capU, capR, capA, coolU, coolR, coolA int
			_ = lrows.Scan(&id, &name, &lat, &lon, &active, &coverage, &handling, &isCP, &isTP, &isHub, &isLab, &capU, &capR, &capA, &coolU, &coolR, &coolA)
			locations = append(locations, map[string]interface{}{
				"id": id.String(), "locationId": id.String(), "name": name,
				"coordinate": map[string]interface{}{"latitude": lat, "longitude": lon},
				"active": active, "coverageKm": coverage, "handlingMinutes": handling,
				"functions": map[string]interface{}{"collection_point": isCP, "transfer_point": isTP, "hub": isHub, "laboratory": isLab},
				"capacity": map[string]interface{}{
					"capacityUnits": capU, "reservedUnits": capR, "availableUnits": capA,
					"cooledCapacityUnits": coolU, "cooledReservedUnits": coolR, "cooledAvailableUnits": coolA,
				},
			})
		}
		lrows.Close()
	}

	connections := []map[string]interface{}{}
	crows, err := a.DB.Query(ctx, `SELECT id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active,
		capacity_units, capacity_reserved, capacity_units-capacity_reserved, cooled_capacity_units, cooled_capacity_reserved, cooled_capacity_units-cooled_capacity_reserved
		FROM connections`)
	if err == nil {
		for crows.Next() {
			var id, fromID, toID uuid.UUID
			var travelMinutes int
			var cost float64
			var cooled, active bool
			var capU, capR, capA, coolU, coolR, coolA int
			_ = crows.Scan(&id, &fromID, &toID, &travelMinutes, &cost, &cooled, &active, &capU, &capR, &capA, &coolU, &coolR, &coolA)
			connections = append(connections, map[string]interface{}{
				"id": id.String(), "connectionId": id.String(), "fromLocationId": fromID.String(), "toLocationId": toID.String(),
				"travelMinutes": travelMinutes, "costUnits": cost, "cooled": cooled, "active": active,
				"capacity": map[string]interface{}{
					"capacityUnits": capU, "reservedUnits": capR, "availableUnits": capA,
					"cooledCapacityUnits": coolU, "cooledReservedUnits": coolR, "cooledAvailableUnits": coolA,
				},
			})
		}
		crows.Close()
	}

	exceptionsList := []map[string]interface{}{}
	erows, err := a.DB.Query(ctx, `SELECT id, sample_id, assignment_id, reason, created_at, resolved FROM exceptions ORDER BY created_at DESC LIMIT 500`)
	if err == nil {
		for erows.Next() {
			var id, sampleID uuid.UUID
			var assignmentID *uuid.UUID
			var reason string
			var createdAt time.Time
			var resolved bool
			_ = erows.Scan(&id, &sampleID, &assignmentID, &reason, &createdAt, &resolved)
			e := map[string]interface{}{"id": id.String(), "sampleId": sampleID.String(), "reason": reason, "createdAt": createdAt.UTC().Format(rfc3339), "resolved": resolved}
			if assignmentID != nil {
				e["assignmentId"] = assignmentID.String()
			}
			exceptionsList = append(exceptionsList, e)
		}
		erows.Close()
	}

	handoffsList := []map[string]interface{}{}
	hrows, err := a.DB.Query(ctx, `SELECT id, sample_id, status, sender_confirmed, receiver_confirmed FROM handoffs ORDER BY created_at DESC LIMIT 500`)
	if err == nil {
		for hrows.Next() {
			var id, sampleID uuid.UUID
			var status string
			var sc, rc bool
			_ = hrows.Scan(&id, &sampleID, &status, &sc, &rc)
			handoffsList = append(handoffsList, map[string]interface{}{"id": id.String(), "sampleId": sampleID.String(), "status": status, "senderConfirmed": sc, "receiverConfirmed": rc})
		}
		hrows.Close()
	}

	var assignmentCountSpread, ineligibleCount int
	_ = a.DB.QueryRow(ctx, `SELECT coalesce(max(c)-min(c),0) FROM (SELECT count(*) c FROM assignments WHERE accepted_worker_id IS NOT NULL GROUP BY accepted_worker_id) t`).Scan(&assignmentCountSpread)
	_ = a.DB.QueryRow(ctx, `SELECT count(*) FROM assignments WHERE status='exception'`).Scan(&ineligibleCount)

	return map[string]interface{}{
		"samples": samples, "workers": workers, "locations": locations, "connections": connections,
		"routes": []map[string]interface{}{}, "handoffs": handoffsList, "delays": []map[string]interface{}{}, "exceptions": exceptionsList,
		"assignmentCountSpread": assignmentCountSpread, "ineligibleAssignmentCount": ineligibleCount,
	}, nil
}

func (a *App) handleReadOperationsState(w http.ResponseWriter, r *http.Request) {
	cu, ok := a.requireAuth(w, r)
	if !ok {
		return
	}
	if !requireActiveRole(w, cu, "administrator", "dispatcher") {
		return
	}
	ops, err := a.buildOperationsState(r.Context())
	if err != nil {
		writeErr(w, errInternal)
		return
	}
	writeData(w, http.StatusOK, ops)
}

// ---------------- Audit search ----------------

func (a *App) handleSearchAuditTrail(w http.ResponseWriter, r *http.Request) {
	cu, ok := a.requireAuth(w, r)
	if !ok {
		return
	}
	if !requireActiveRole(w, cu, "administrator", "dispatcher") {
		return
	}
	var req struct {
		Query      string  `json:"query"`
		ActorID    string  `json:"actorId"`
		EntityType string  `json:"entityType"`
		EntityID   string  `json:"entityId"`
		Action     string  `json:"action"`
		Role       string  `json:"role"`
		Success    *bool   `json:"success"`
		FromTime   *string `json:"fromTime"`
		ToTime     *string `json:"toTime"`
		Limit      *int    `json:"limit"`
		Offset     *int    `json:"offset"`
		Order      string  `json:"order"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, errInvalidJSON)
		return
	}
	limit := 500
	if req.Limit != nil {
		limit = *req.Limit
	}
	offset := 0
	if req.Offset != nil {
		offset = *req.Offset
	}
	order := "DESC"
	orderLabel := "newest_first"
	if req.Order == "oldest_first" {
		order = "ASC"
		orderLabel = "oldest_first"
	}

	ctx := r.Context()
	where := "TRUE"
	args := []interface{}{}
	add := func(cond string, val interface{}) {
		args = append(args, val)
		where += " AND " + cond + " $" + itoa(len(args))
	}
	if req.ActorID != "" {
		add("actor_id =", req.ActorID)
	}
	if req.EntityType != "" {
		add("entity_type =", req.EntityType)
	}
	if req.EntityID != "" {
		add("entity_id =", req.EntityID)
	}
	if req.Action != "" {
		add("action =", req.Action)
	}
	if req.Role != "" {
		add("role =", req.Role)
	}
	if req.Success != nil {
		add("success =", *req.Success)
	}
	if req.FromTime != nil {
		if t, err := parseTime(*req.FromTime); err == nil {
			add("occurred_at >=", t)
		}
	}
	if req.ToTime != nil {
		if t, err := parseTime(*req.ToTime); err == nil {
			add("occurred_at <=", t)
		}
	}
	if req.Query != "" {
		args = append(args, "%"+req.Query+"%")
		where += " AND (action ILIKE $" + itoa(len(args)) + " OR entity_id ILIKE $" + itoa(len(args)) + ")"
	}

	var total int
	_ = a.DB.QueryRow(ctx, `SELECT count(*) FROM audit_log WHERE `+where, args...).Scan(&total)

	args2 := append(append([]interface{}{}, args...), limit, offset)
	sql := `SELECT id, coalesce(actor_id::text,''), coalesce(role,''), action, entity_type, coalesce(entity_id,''), success, occurred_at, details
		FROM audit_log WHERE ` + where + ` ORDER BY occurred_at ` + order + `, id ` + order + ` LIMIT $` + itoa(len(args2)-1) + ` OFFSET $` + itoa(len(args2))
	rows, err := a.DB.Query(ctx, sql, args2...)
	if err != nil {
		writeErr(w, errInternal)
		return
	}
	defer rows.Close()
	entries := []map[string]interface{}{}
	for rows.Next() {
		var id int64
		var actorID, role, action, entityType, entityID string
		var success bool
		var occurredAt time.Time
		var details []byte
		_ = rows.Scan(&id, &actorID, &role, &action, &entityType, &entityID, &success, &occurredAt, &details)
		var detailsMap map[string]interface{}
		_ = jsonUnmarshal(details, &detailsMap)
		entries = append(entries, map[string]interface{}{
			"auditId": itoa64(id), "actorId": actorID, "role": role, "actorRole": role, "action": action,
			"entityType": entityType, "entityId": entityID, "success": success,
			"occurredAt": occurredAt.UTC().Format(rfc3339), "details": detailsMap,
		})
	}
	hasMore := offset+len(entries) < total
	var nextOffset interface{}
	if hasMore {
		nextOffset = offset + len(entries)
	}
	writeData(w, http.StatusOK, map[string]interface{}{
		"entries": entries, "total": total, "returned": len(entries), "offset": offset, "limit": limit,
		"order": orderLabel, "hasMore": hasMore, "nextOffset": nextOffset,
	})
}

func itoa64(n int64) string {
	return itoa(int(n))
}
"}

