func (a *App) loadLegs(ctxQuerier querier, journeyID uuid.UUID) []map[string]interface{} {
	rows, err := ctxQuerier.Query(`SELECT id, sequence, status, from_location_id, to_location_id, accepted_worker_id, sample_id FROM assignments
		WHERE journey_id=$1 ORDER BY sequence ASC`, journeyID)
	if err != nil {
		return nil
	}
	defer rows.Close()
	var out []map[string]interface{}
	for rows.Next() {
		var id, sampleID uuid.UUID
		var seq int
		var status string
		var fromLoc, toLoc, worker *uuid.UUID
		_ = rows.Scan(&id, &seq, &status, &fromLoc, &toLoc, &worker, &sampleID)
		leg := map[string]interface{}{"assignmentId": id.String(), "sequence": seq, "status": status}
