	err := a.DB.QueryRow(ctx, `SELECT plan_version, route_mode, status, estimated_delivery_at, parent_journey_id FROM journeys WHERE id=$1`, req.JourneyID).
		Scan(&planVersion, &routeMode, &status, &estimatedDelivery, &parentJourneyID)
