	if isAdminOrDispatcher(cu.ActiveRole) {
		writeData(w, http.StatusOK, a.fullJourneyPlan(ctx, req.JourneyID, planVersion, routeMode, status, estimatedDelivery, parentJourneyID, sampleIDs))
		return
