// ---------------- Plan-version-checked mutations ----------------

func (a *App) checkPlanVersion(ctx context.Context, journeyID uuid.UUID, expected int) (int, string, error) {
	var current int
	var status string
	err := a.DB.QueryRow(ctx, `SELECT plan_version, status FROM journeys WHERE id=$1`, journeyID).Scan(&current, &status)
	if err != nil {
		return 0, "", err
	}
	if current != expected {
		return current, status, newErr(http.StatusConflict, "plan_version_mismatch", "the journey has since been updated")
	}
	return current, status, nil
}

type cancelJourneyReq struct {
	JourneyID           uuid.UUID `json:"journeyId"`
	ExpectedPlanVersion int       `json:"expectedPlanVersion"`
	Reason              string    `json:"reason"`
	IdempotencyKey      string    `json:"idempotencyKey"`
}

func (a *App) handleCancelJourney(w http.ResponseWriter, r *http.Request) {
	cu, ok := a.requireAuth(w, r)
	if !ok {
		return
	}
	if !requireActiveRole(w, cu, "administrator", "dispatcher") {
		return
	}
	body, _ := io.ReadAll(r.Body)
	var req cancelJourneyReq
	if err := jsonUnmarshal(body, &req); err != nil {
		writeErr(w, errInvalidJSON)
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, errIdemRequired)
		return
	}
	ctx := r.Context()
	if status, resp, cached, conflict := a.checkIdempotency(ctx, req.IdempotencyKey, "cancel-journey", cu.ID, body); cached {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(status)
		_, _ = w.Write(resp)
		return
	} else if conflict {
		writeErr(w, newErr(http.StatusConflict, "idempotency_conflict", "idempotencyKey reused with a different request"))
		return
	}

	_, _, err := a.checkPlanVersion(ctx, req.JourneyID, req.ExpectedPlanVersion)
	if err != nil {
		if apiErr, ok := err.(*apiError); ok {
			writeErr(w, apiErr)
		} else {
			writeErr(w, errNotFound)
		}
		return
	}

	_, _ = a.DB.Exec(ctx, `UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status NOT IN ('completed','cancelled')`, req.JourneyID)
	_, err = a.DB.Exec(ctx, `UPDATE journeys SET status='cancelled', plan_version=plan_version+1, updated_at=now() WHERE id=$1`, req.JourneyID)
	if err != nil {
		writeErr(w, errInternal)
		return
	}
	a.releaseCapacityForJourney(ctx, req.JourneyID)
	rows, _ := a.DB.Query(ctx, `SELECT sample_id FROM journey_samples WHERE journey_id=$1`, req.JourneyID)
	for rows.Next() {
		var sid uuid.UUID
		_ = rows.Scan(&sid)
		_, _ = a.DB.Exec(ctx, `UPDATE samples SET status='cancelled' WHERE id=$1`, sid)
		a.recordTimeline(ctx, "sample", sid, "journey_cancelled", &cu.ID, cu.ActiveRole, true, map[string]interface{}{"journeyId": req.JourneyID.String(), "reason": req.Reason})
	}
	rows.Close()
	a.recordAudit(ctx, &cu.ID, cu.ActiveRole, "cancel_journey", "journey", req.JourneyID.String(), true, map[string]interface{}{"reason": req.Reason})
	a.emit(ctx, "journey_cancelled", "journey", req.JourneyID.String(), "dispatcher", nil, map[string]interface{}{"journeyId": req.JourneyID.String()})

	resp := map[string]interface{}{"journeyId": req.JourneyID.String(), "status": "cancelled"}
	a.saveIdempotency(ctx, req.IdempotencyKey, "cancel-journey", cu.ID, body, http.StatusOK, map[string]interface{}{"data": resp})
	writeData(w, http.StatusOK, resp)
}

type rerouteJourneyReq struct {
	JourneyID           uuid.UUID `json:"journeyId"`
	ExpectedPlanVersion int       `json:"expectedPlanVersion"`
	Reason              string    `json:"reason"`
	IdempotencyKey      string    `json:"idempotencyKey"`
}

func (a *App) handleRerouteJourney(w http.ResponseWriter, r *http.Request) {
	cu, ok := a.requireAuth(w, r)
	if !ok {
		return
	}
	if !requireActiveRole(w, cu, "administrator", "dispatcher") {
		return
	}
	body, _ := io.ReadAll(r.Body)
	var req rerouteJourneyReq
	if err := jsonUnmarshal(body, &req); err != nil {
		writeErr(w, errInvalidJSON)
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, errIdemRequired)
		return
	}
	ctx := r.Context()
	if status, resp, cached, conflict := a.checkIdempotency(ctx, req.IdempotencyKey, "reroute-journey", cu.ID, body); cached {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(status)
		_, _ = w.Write(resp)
		return
	} else if conflict {
		writeErr(w, newErr(http.StatusConflict, "idempotency_conflict", "idempotencyKey reused with a different request"))
		return
	}

	_, journeyStatus, err := a.checkPlanVersion(ctx, req.JourneyID, req.ExpectedPlanVersion)
	if err != nil {
		if apiErr, ok := err.(*apiError); ok {
			writeErr(w, apiErr)
		} else {
			writeErr(w, errNotFound)
		}
		return
	}
	if journeyStatus == "completed" || journeyStatus == "cancelled" {
		writeErr(w, newErr(http.StatusConflict, "journey_finished", "cannot replan a finished journey"))
		return
	}

	newJourneyID, ok2 := a.replanJourney(ctx, req.JourneyID, req.Reason)
	if !ok2 {
		resp := map[string]interface{}{"journeyId": req.JourneyID.String(), "status": "expired"}
		a.saveIdempotency(ctx, req.IdempotencyKey, "reroute-journey", cu.ID, body, http.StatusOK, map[string]interface{}{"data": resp})
		writeData(w, http.StatusOK, resp)
		return
	}
	a.recordAudit(ctx, &cu.ID, cu.ActiveRole, "reroute_journey", "journey", req.JourneyID.String(), true, map[string]interface{}{"reason": req.Reason, "replacementJourneyId": newJourneyID.String()})
	resp := map[string]interface{}{"journeyId": req.JourneyID.String(), "replacementJourneyId": newJourneyID.String(), "status": "replaced"}
	a.saveIdempotency(ctx, req.IdempotencyKey, "reroute-journey", cu.ID, body, http.StatusOK, map[string]interface{}{"data": resp})
	writeData(w, http.StatusOK, resp)
}

// replanJourney preserves completed work and replaces only the unfinished
// remainder of a journey with a fresh plan (a new plan version), honoring
// the "only one active replacement plan" rule.
func (a *App) replanJourney(ctx context.Context, journeyID uuid.UUID, reason string) (uuid.UUID, bool) {
	var sampleID uuid.UUID
	err := a.DB.QueryRow(ctx, `SELECT sample_id FROM journey_samples js JOIN samples s ON s.id=js.sample_id WHERE js.journey_id=$1 LIMIT 1`, journeyID).Scan(&sampleID)
	if err != nil {
		return uuid.Nil, false
	}
	var currentHolder *uuid.UUID
	var deadline time.Time
	var sampleTypeID uuid.UUID
	var lat, lon float64
	_ = a.DB.QueryRow(ctx, `SELECT current_holder_id, delivery_deadline, sample_type_id, latitude, longitude FROM samples WHERE id=$1`, sampleID).
		Scan(&currentHolder, &deadline, &sampleTypeID, &lat, &lon)

	st, err := a.loadSampleType(ctx, sampleTypeID)
	if err != nil {
		return uuid.Nil, false
	}

	locs, conns, err := a.loadNetwork(ctx)
	if err != nil {
		return uuid.Nil, false
	}

	// Determine the current location to replan from: the last completed stop's location,
	// falling back to the nearest active collection point.
	var startLoc *netLocation
	var lastCompletedLoc *uuid.UUID
	_ = a.DB.QueryRow(ctx, `SELECT to_location_id FROM assignments WHERE journey_id=$1 AND status='completed' ORDER BY sequence DESC LIMIT 1`, journeyID).Scan(&lastCompletedLoc)
	if lastCompletedLoc != nil {
		startLoc = locs[*lastCompletedLoc]
	}
	if startLoc == nil {
		startLoc = nearestCollectionPoint(locs, lat, lon)
	}
	if startLoc == nil {
		a.expireSample(ctx, sampleID, "no_route")
		return uuid.Nil, false
	}

	isDest := func(l *netLocation) bool { return l.IsLaboratory && l.AcceptedTypes[st.ID] }
	path, minutes, destID, found := shortestRoute(locs, conns, startLoc.ID, st.RequiresCooled, isDest)
	if !found && isDest(startLoc) {
		destID = startLoc.ID
		found = true
		minutes = 0
	}
	if !found {
		a.expireSample(ctx, sampleID, "no_route")
		return uuid.Nil, false
	}
	eta := time.Now().Add(time.Duration(minutes) * time.Minute)
	if eta.After(deadline) {
		a.expireSample(ctx, sampleID, "deadline_unreachable")
		return uuid.Nil, false
	}

	// Cancel unfinished assignments of the old journey and release their reservations.
	_, _ = a.DB.Exec(ctx, `UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status NOT IN ('completed','cancelled')`, journeyID)
	a.releaseCapacityForJourney(ctx, journeyID)

	var newPlanVersion int
	_ = a.DB.QueryRow(ctx, `UPDATE journeys SET status='replaced', plan_version=plan_version+1, updated_at=now() WHERE id=$1 RETURNING plan_version`, journeyID).Scan(&newPlanVersion)

	newJourneyID, err := a.createJourneyForSample(ctx, sampleID, startLoc, path, destID, locs, true, st, eta)
	if err != nil {
		return uuid.Nil, false
	}
	_, _ = a.DB.Exec(ctx, `UPDATE journeys SET parent_journey_id=$1, plan_version=$2 WHERE id=$3`, journeyID, newPlanVersion, newJourneyID)
	_, _ = a.DB.Exec(ctx, `UPDATE journeys SET active_replacement_plan_id=$1, replan_status='replaced' WHERE id=$2`, newJourneyID, journeyID)

	a.recordTimeline(ctx, "sample", sampleID, "journey_replanned", nil, "", true, map[string]interface{}{"reason": reason, "newJourneyId": newJourneyID.String()})
	a.emit(ctx, "journey_replanned", "journey", journeyID.String(), "dispatcher", nil, map[string]interface{}{"newJourneyId": newJourneyID.String()})
	return newJourneyID, true
}

func (a *App) expireSample(ctx context.Context, sampleID uuid.UUID, reason string) {
	_, _ = a.DB.Exec(ctx, `UPDATE samples SET status='expired', exception_reason=$1 WHERE id=$2`, reason, sampleID)
	a.recordTimeline(ctx, "sample", sampleID, "expired", nil, "", true, map[string]interface{}{"reason": reason})
	a.emit(ctx, "sample_expired", "sample", sampleID.String(), "dispatcher", nil, map[string]interface{}{"reason": reason, "sampleId": sampleID.String()})
}

type reportDisruptionReq struct {
	ResourceType   string `json:"resourceType"`
	ResourceID     string `json:"resourceId"`
	Reason         string `json:"reason"`
	OccurredAt     string `json:"occurredAt"`
	IdempotencyKey string `json:"idempotencyKey"`
}

func (a *App) handleReportDisruption(w http.ResponseWriter, r *http.Request) {
	cu, ok := a.requireAuth(w, r)
	if !ok {
		return
	}
	if !requireActiveRole(w, cu, "administrator", "dispatcher") {
		return
	}
	body, _ := io.ReadAll(r.Body)
	var req reportDisruptionReq
	if err := jsonUnmarshal(body, &req); err != nil {
		writeErr(w, errInvalidJSON)
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, errIdemRequired)
		return
	}
	ctx := r.Context()
	if status, resp, cached, conflict := a.checkIdempotency(ctx, req.IdempotencyKey, "report-disruption", cu.ID, body); cached {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(status)
		_, _ = w.Write(resp)
		return
	} else if conflict {
		writeErr(w, newErr(http.StatusConflict, "idempotency_conflict", "idempotencyKey reused with a different request"))
		return
	}

	resourceUUID, parseErr := uuid.Parse(req.ResourceID)

	// Deactivate the resource so future planning avoids it.
	switch req.ResourceType {
	case "location", "node", "laboratory":
		if parseErr == nil {
			_, _ = a.DB.Exec(ctx, `UPDATE locations SET active=FALSE WHERE id=$1`, resourceUUID)
			a.bumpNetworkRevision(ctx)
		}
	case "connection", "route":
		if parseErr == nil {
			_, _ = a.DB.Exec(ctx, `UPDATE connections SET active=FALSE WHERE id=$1`, resourceUUID)
			a.bumpNetworkRevision(ctx)
		}
	case "worker":
		if parseErr == nil {
			_, _ = a.DB.Exec(ctx, `UPDATE worker_availability SET available=FALSE WHERE worker_id=$1`, resourceUUID)
		}
	}

	// Replan every unfinished journey that touches the disrupted resource.
	replannedJourneys := []string{}
	var rows interface {
		Next() bool
		Scan(...interface{}) error
		Close()
	}
	var err error
	switch req.ResourceType {
	case "worker":
		rows, err = a.DB.Query(ctx, `SELECT DISTINCT journey_id FROM assignments WHERE (offered_worker_id=$1 OR accepted_worker_id=$1)
			AND status NOT IN ('completed','cancelled')`, resourceUUID)
	case "location", "node", "laboratory":
		rows, err = a.DB.Query(ctx, `SELECT DISTINCT journey_id FROM assignments WHERE (from_location_id=$1 OR to_location_id=$1 OR node_id=$1 OR laboratory_id=$1)
			AND status NOT IN ('completed','cancelled')`, resourceUUID)
	case "connection", "route":
		rows, err = a.DB.Query(ctx, `SELECT DISTINCT journey_id FROM assignments WHERE connection_id=$1 AND status NOT IN ('completed','cancelled')`, resourceUUID)
	case "capacity":
		rows, err = a.DB.Query(ctx, `SELECT DISTINCT journey_id FROM assignments WHERE (node_id=$1 OR laboratory_id=$1 OR connection_id=$1) AND status NOT IN ('completed','cancelled')`, resourceUUID)
	}
	if err == nil && rows != nil {
		var journeyIDs []uuid.UUID
		for rows.Next() {
			var jid uuid.UUID
			_ = rows.Scan(&jid)
			journeyIDs = append(journeyIDs, jid)
		}
		rows.Close()
		for _, jid := range journeyIDs {
			var status string
			_ = a.DB.QueryRow(ctx, `SELECT status FROM journeys WHERE id=$1`, jid).Scan(&status)
			if status == "completed" || status == "cancelled" || status == "replaced" {
				continue
			}
			if newID, ok2 := a.replanJourney(ctx, jid, "disruption:"+req.ResourceType); ok2 {
				replannedJourneys = append(replannedJourneys, newID.String())
			}
		}
	}

	a.recordAudit(ctx, &cu.ID, cu.ActiveRole, "report_disruption", req.ResourceType, req.ResourceID, true, map[string]interface{}{"reason": req.Reason, "replannedJourneys": replannedJourneys})

	resp := map[string]interface{}{"resourceType": req.ResourceType, "resourceId": req.ResourceID, "replannedJourneyIds": replannedJourneys}
	a.saveIdempotency(ctx, req.IdempotencyKey, "report-disruption", cu.ID, body, http.StatusOK, map[string]interface{}{"data": resp})
	writeData(w, http.StatusOK, resp)
}

