func (a *App) handleReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	cu, ok := a.requireAuth(w, r)
	if !ok {
		return
	}
	var req struct {
		JourneyID uuid.UUID `json:"journeyId"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeErr(w, errInvalidJSON)
		return
	}
	ctx := r.Context()
	var planVersion int
	var routeMode, status string
	var estimatedDelivery *time.Time
	var parentJourneyID *uuid.UUID
	err := a.DB.QueryRow(ctx, `SELECT plan_version, route_mode, status, estimated_delivery_at, parent_journey_id FROM journeys WHERE id=$1`, req.JourneyID).
		Scan(&planVersion, &routeMode, &status, &estimatedDelivery, &parentJourneyID)
	if err != nil {
		writeErr(w, errNotFound)
		return
	}

	sampleIDs := []string{}
	srows, _ := a.DB.Query(ctx, `SELECT sample_id FROM journey_samples WHERE journey_id=$1`, req.JourneyID)
	var firstSample *uuid.UUID
	for srows.Next() {
		var id uuid.UUID
		_ = srows.Scan(&id)
		sampleIDs = append(sampleIDs, id.String())
		if firstSample == nil {
			firstSample = &id
		}
	}
	srows.Close()

	if isAdminOrDispatcher(cu.ActiveRole) {
		writeData(w, http.StatusOK, a.fullJourneyPlan(ctx, req.JourneyID, planVersion, routeMode, status, estimatedDelivery, parentJourneyID, sampleIDs))
		return
	}
	if cu.ActiveRole == "requester" {
		if firstSample == nil {
			writeErr(w, errForbidden)
			return
		}
		var requesterID uuid.UUID
		_ = a.DB.QueryRow(ctx, `SELECT requester_id FROM samples WHERE id=$1`, *firstSample).Scan(&requesterID)
		if requesterID != cu.ID {
			writeErr(w, errForbidden)
			return
		}
		writeData(w, http.StatusOK, a.requesterJourneyPlan(ctx, req.JourneyID, planVersion, routeMode, status, estimatedDelivery, sampleIDs))
		return
	}
	// Worker roles: only their assigned legs.
	var count int
	_ = a.DB.QueryRow(ctx, `SELECT count(*) FROM assignments WHERE journey_id=$1 AND (offered_worker_id=$2 OR accepted_worker_id=$2)`, req.JourneyID, cu.ID).Scan(&count)
	if count == 0 {
		writeErr(w, errForbidden)
		return
	}
	writeData(w, http.StatusOK, a.workerJourneyPlan(ctx, req.JourneyID, cu.ID, planVersion, routeMode, status, estimatedDelivery, parentJourneyID, sampleIDs))
}

func (a *App) loadLegs(ctx context.Context, journeyID uuid.UUID) []map[string]interface{} {
	rows, err := a.DB.Query(ctx, `SELECT id, sequence, status, from_location_id, to_location_id, accepted_worker_id, sample_id, kind FROM assignments
		WHERE journey_id=$1 ORDER BY sequence ASC`, journeyID)
	if err != nil {
		return []map[string]interface{}{}
	}
	defer rows.Close()
	out := []map[string]interface{}{}
	for rows.Next() {
		var id, sampleID uuid.UUID
		var seq int
		var status, kind string
		var fromLoc, toLoc, worker *uuid.UUID
		_ = rows.Scan(&id, &seq, &status, &fromLoc, &toLoc, &worker, &sampleID, &kind)
		leg := map[string]interface{}{"assignmentId": id.String(), "sequence": seq, "status": status, "kind": kind}
		if fromLoc != nil {
			leg["fromLocationId"] = fromLoc.String()
		}
		if toLoc != nil {
			leg["toLocationId"] = toLoc.String()
		}
		if worker != nil {
			leg["workerId"] = worker.String()
		}
		leg["sampleId"] = sampleID.String()
		out = append(out, leg)
	}
	return out
}

func (a *App) loadStops(ctx context.Context, journeyID uuid.UUID) []map[string]interface{} {
	rows, err := a.DB.Query(ctx, `SELECT id, location_id, stop_type, sequence, estimated_at, dwell_minutes, completed_at FROM journey_stops
		WHERE journey_id=$1 ORDER BY sequence ASC`, journeyID)
	if err != nil {
		return []map[string]interface{}{}
	}
	defer rows.Close()
	out := []map[string]interface{}{}
	for rows.Next() {
		var id, locID uuid.UUID
		var stopType string
		var seq, dwell int
		var estimatedAt, completedAt *time.Time
		_ = rows.Scan(&id, &locID, &stopType, &seq, &estimatedAt, &dwell, &completedAt)
		s := map[string]interface{}{"stopId": id.String(), "locationId": locID.String(), "stopType": stopType, "sequence": seq, "dwellMinutes": dwell}
		if estimatedAt != nil {
			s["estimatedAt"] = estimatedAt.UTC().Format(rfc3339)
		}
		if completedAt != nil {
			s["completedAt"] = completedAt.UTC().Format(rfc3339)
		}
		out = append(out, s)
	}
	return out
}

func (a *App) fullJourneyPlan(ctx context.Context, journeyID uuid.UUID, planVersion int, routeMode, status string, estimatedDelivery *time.Time, parentJourneyID *uuid.UUID, sampleIDs []string) map[string]interface{} {
	data := map[string]interface{}{
