// ---------------- Plan-version-checked mutations ----------------

func (a *App) checkPlanVersion(ctx context.Context, journeyID uuid.UUID, expected int) (int, string, error) {
	var current int
	var status string
	err := a.DB.QueryRow(ctx, `SELECT plan_version, status FROM journeys WHERE id=$1`, journeyID).Scan(&current, &status)
	if err != nil {
		return 0, "", err
	}
	if current != expected {
		return current, status, newErr(http.StatusConflict, "plan_version_mismatch", "the journey has since been updated")
	}
	return current, status, nil
}

type cancelJourneyReq struct {
	JourneyID           uuid.UUID `json:"journeyId"`
	ExpectedPlanVersion int       `json:"expectedPlanVersion"`
	Reason              string    `json:"reason"`
	IdempotencyKey      string    `json:"idempotencyKey"`
}

func (a *App) handleCancelJourney(w http.ResponseWriter, r *http.Request) {
	cu, ok := a.requireAuth(w, r)
	if !ok {
		return
	}
	if !requireActiveRole(w, cu, "administrator", "dispatcher") {
		return
	}
	body, _ := io.ReadAll(r.Body)
	var req cancelJourneyReq
	if err := jsonUnmarshal(body, &req); err != nil {
		writeErr(w, errInvalidJSON)
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, errIdemRequired)
		return
	}
	ctx := r.Context()
	if status, resp, cached, conflict := a.checkIdempotency(ctx, req.IdempotencyKey, "cancel-journey", cu.ID, body); cached {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(status)
		_, _ = w.Write(resp)
		return
	} else if conflict {
		writeErr(w, newErr(http.StatusConflict, "idempotency_conflict", "idempotencyKey reused with a different request"))
		return
	}

	_, _, err := a.checkPlanVersion(ctx, req.JourneyID, req.ExpectedPlanVersion)
	if err != nil {
		if apiErr, ok := err.(*apiError); ok {
			writeErr(w, apiErr)
		} else {
			writeErr(w, errNotFound)
		}
		return
	}

	_, _ = a.DB.Exec(ctx, `UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status NOT IN ('completed','cancelled')`, req.JourneyID)
	_, err = a.DB.Exec(ctx, `UPDATE journeys SET status='cancelled', plan_version=plan_version+1, updated_at=now() WHERE id=$1`, req.JourneyID)
	if err != nil {
		writeErr(w, errInternal)
		return
	}
	a.releaseCapacityForJourney(ctx, req.JourneyID)
	rows, _ := a.DB.Query(ctx, `SELECT sample_id FROM journey_samples WHERE journey_id=$1`, req.JourneyID)
	for rows.Next() {
		var sid uuid.UUID
		_ = rows.Scan(&sid)
		_, _ = a.DB.Exec(ctx, `UPDATE samples SET status='cancelled' WHERE id=$1`, sid)
		a.recordTimeline(ctx, "sample", sid, "journey_cancelled", &cu.ID, cu.ActiveRole, true, map[string]interface{}{"journeyId": req.JourneyID.String(), "reason": req.Reason})
	}
	rows.Close()
	a.recordAudit(ctx, &cu.ID, cu.ActiveRole, "cancel_journey", "journey", req.JourneyID.String(), true, map[string]interface{}{"reason": req.Reason})
	a.emit(ctx, "journey_cancelled", "journey", req.JourneyID.String(), "dispatcher", nil, map[string]interface{}{"journeyId": req.JourneyID.String()})

	resp := map[string]interface{}{"journeyId": req.JourneyID.String(), "status": "cancelled"}
	a.saveIdempotency(ctx, req.IdempotencyKey, "cancel-journey", cu.ID, body, http.StatusOK, map[string]interface{}{"data": resp})
	writeData(w, http.StatusOK, resp)
}

type rerouteJourneyReq struct {
	JourneyID           uuid.UUID `json:"journeyId"`
	ExpectedPlanVersion int       `json:"expectedPlanVersion"`
	Reason              string    `json:"reason"`
	IdempotencyKey      string    `json:"idempotencyKey"`
