}

func (a *App) handleEditActivePlan(w http.ResponseWriter, r *http.Request) {
	cu, ok := a.requireAuth(w, r)
	if !ok {
		return
	}
	if !requireActiveRole(w, cu, "administrator", "dispatcher") {
		return
	}
	body, _ := io.ReadAll(r.Body)
	var req editActivePlanReq
	if err := jsonUnmarshal(body, &req); err != nil {
		writeErr(w, errInvalidJSON)
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, errIdemRequired)
		return
	}
	ctx := r.Context()
	if status, resp, cached, conflict := a.checkIdempotency(ctx, req.IdempotencyKey, "edit-active-plan", cu.ID, body); cached {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(status)
		_, _ = w.Write(resp)
		return
	} else if conflict {
		writeErr(w, newErr(http.StatusConflict, "idempotency_conflict", "idempotencyKey reused with a different request"))
		return
	}
	_, journeyStatus, err := a.checkPlanVersion(ctx, req.JourneyID, req.ExpectedPlanVersion)
	if err != nil {
		if apiErr, ok := err.(*apiError); ok {
			writeErr(w, apiErr)
		} else {
			writeErr(w, errNotFound)
		}
		return
	}
	if journeyStatus == "completed" || journeyStatus == "cancelled" {
		writeErr(w, newErr(http.StatusConflict, "journey_finished", "cannot edit a finished journey"))
		return
	}

	switch req.ChangeType {
	case "reassign_worker", "replace_worker":
		if assignmentIDStr, ok2 := req.Changes["assignmentId"].(string); ok2 {
			if assignmentID, err := uuid.Parse(assignmentIDStr); err == nil {
				_, _ = a.DB.Exec(ctx, `UPDATE assignments SET status='unassigned', offered_worker_id=NULL, accepted_worker_id=NULL,
					offer_expires_at=NULL WHERE id=$1 AND journey_id=$2`, assignmentID, req.JourneyID)
				a.offerAssignment(ctx, assignmentID)
			}
		}
	case "cancel_work":
		_, _ = a.DB.Exec(ctx, `UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status NOT IN ('completed','cancelled')`, req.JourneyID)
	case "reroute", "replace_route":
		a.replanJourney(ctx, req.JourneyID, "edit_active_plan")
	}
	_, _ = a.DB.Exec(ctx, `UPDATE journeys SET plan_version=plan_version+1, updated_at=now() WHERE id=$1`, req.JourneyID)
	a.recordAudit(ctx, &cu.ID, cu.ActiveRole, "edit_active_plan", "journey", req.JourneyID.String(), true, map[string]interface{}{"changeType": req.ChangeType})

	var newVersion int
	_ = a.DB.QueryRow(ctx, `SELECT plan_version FROM journeys WHERE id=$1`, req.JourneyID).Scan(&newVersion)
	resp := map[string]interface{}{"journeyId": req.JourneyID.String(), "planVersion": newVersion, "changeType": req.ChangeType}
	a.saveIdempotency(ctx, req.IdempotencyKey, "edit-active-plan", cu.ID, body, http.StatusOK, map[string]interface{}{"data": resp})
	writeData(w, http.StatusOK, resp)
}
"}

