{"command":"create","path":"/workspace/frontend/src/lib/api.ts","file_text":"// Thin wrapper around the backend JSON API. All endpoints are POST (except a
// couple of GETs) and return either `{ data: ... }` on success or
// `{ error, code }` on failure.

const API_BASE = "/api";

export class ApiError extends Error {
  code: string;
  status: number;
  constructor(message: string, code: string, status: number) {
    super(message);
    this.code = code;
    this.status = status;
  }
}

function tokenKey() {
  return "lsp_session_token";
}

export function getToken(): string | null {
  return localStorage.getItem(tokenKey());
}

export function setToken(token: string | null) {
  if (token) {
    localStorage.setItem(tokenKey(), token);
  } else {
    localStorage.removeItem(tokenKey());
  }
}

async function request<T>(
  method: "GET" | "POST",
  path: string,
  body?: unknown,
): Promise<T> {
  const headers: Record<string, string> = {};
  const token = getToken();
  if (token) {
    headers["Authorization"] = `Bearer ${token}`;
  }
  let payload: string | undefined;
  if (method === "POST") {
    headers["Content-Type"] = "application/json";
    payload = JSON.stringify(body ?? {});
  }
  const resp = await fetch(`${API_BASE}${path}`, {
    method,
    headers,
    body: payload,
  });
  const text = await resp.text();
  let json: any = {};
  if (text) {
    try {
      json = JSON.parse(text);
    } catch {
      json = {};
    }
  }
  if (!resp.ok) {
    throw new ApiError(json.error || "request failed", json.code || "unknown_error", resp.status);
  }
  return (json.data ?? json) as T;
}

export const api = {
  get: <T>(path: string) => request<T>("GET", path),
  post: <T>(path: string, body?: unknown) => request<T>("POST", path, body),
};

export function newIdempotencyKey(): string {
  return (
    "idem-" +
    Date.now().toString(36) +
    "-" +
    Math.random().toString(36).slice(2, 12)
  );
}
"}

