{"command":"create","path":"/workspace/frontend/src/lib/AuthContext.tsx","file_text":"import React, { createContext, useCallback, useContext, useEffect, useState } from "react";
import { api, getToken, setToken } from "./api";
import type { CurrentUserInfo, Role } from "./types";

interface BootstrapData {
  user: CurrentUserInfo;
  serverTime: string;
  requesterSamples?: unknown[];
  operations?: unknown;
}

interface AuthContextValue {
  user: CurrentUserInfo | null;
  loading: boolean;
  login: (username: string, password: string) => Promise<void>;
  logout: () => void;
  selectRole: (role: Role) => Promise<void>;
  refresh: () => Promise<void>;
}

const AuthContext = createContext<AuthContextValue | undefined>(undefined);

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<CurrentUserInfo | null>(null);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    if (!getToken()) {
      setUser(null);
      setLoading(false);
      return;
    }
    try {
      const data = await api.get<BootstrapData>("/ui/bootstrap");
      setUser(data.user);
    } catch {
      setToken(null);
      setUser(null);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    refresh();
  }, [refresh]);

  const login = useCallback(async (username: string, password: string) => {
    const data = await api.post<{
      sessionToken: string;
      userId: string;
      roles: Role[];
      activeRole: Role | "";
    }>("/authenticate-user", { username, password });
    setToken(data.sessionToken);
    await refresh();
  }, [refresh]);

  const logout = useCallback(() => {
    setToken(null);
    setUser(null);
  }, []);

  const selectRole = useCallback(async (role: Role) => {
    await api.post("/select-active-role", { role });
    await refresh();
  }, [refresh]);

  return (
    <AuthContext.Provider value={{ user, loading, login, logout, selectRole, refresh }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth(): AuthContextValue {
  const ctx = useContext(AuthContext);
  if (!ctx) {
    throw new Error("useAuth must be used within AuthProvider");
  }
  return ctx;
}
"}

