{"command":"create","path":"/workspace/frontend/src/App.tsx","file_text":"import React from "react";
import { Navigate, Route, Routes } from "react-router-dom";
import { useAuth } from "./lib/AuthContext";
import TopBar from "./components/TopBar";
import LoginPage from "./pages/LoginPage";
import RoleSelectPage from "./pages/RoleSelectPage";
import DashboardPage from "./pages/DashboardPage";
import ServiceabilityPage from "./pages/ServiceabilityPage";
import NewRequestPage from "./pages/NewRequestPage";
import SampleDetailPage from "./pages/SampleDetailPage";
import MonitorPage from "./pages/MonitorPage";
import AuditPage from "./pages/AuditPage";
import AdminPage from "./pages/AdminPage";
import MapPage from "./pages/MapPage";

function RequireAuth({ children }: { children: React.ReactNode }) {
  const { user, loading } = useAuth();
  if (loading) {
    return <div className="main-content">Loading…</div>;
  }
  if (!user) {
    return <Navigate to="/login" replace />;
  }
  if (user.roleSelectionRequired && user.roles.length > 1) {
    return <Navigate to="/select-role" replace />;
  }
  return <>{children}</>;
}

export default function App() {
  const { user, loading } = useAuth();

  return (
    <div className="app-shell">
      <TopBar />
      <div className="main-content">
        <Routes>
          <Route path="/login" element={loading ? <div>Loading…</div> : user ? <Navigate to="/" replace /> : <LoginPage />} />
          <Route
            path="/select-role"
            element={
              <RequireAuthLoose>
                <RoleSelectPage />
              </RequireAuthLoose>
            }
          />
          <Route
            path="/"
            element={
              <RequireAuth>
                <DashboardPage />
              </RequireAuth>
            }
          />
          <Route
            path="/serviceability"
            element={
              <RequireAuth>
                <ServiceabilityPage />
              </RequireAuth>
            }
          />
          <Route
            path="/new-request"
            element={
              <RequireAuth>
                <NewRequestPage />
              </RequireAuth>
            }
          />
          <Route
            path="/samples/:sampleId"
            element={
              <RequireAuth>
                <SampleDetailPage />
              </RequireAuth>
            }
          />
          <Route
            path="/monitor"
            element={
              <RequireAuth>
                <MonitorPage />
              </RequireAuth>
            }
          />
          <Route
            path="/audit"
            element={
              <RequireAuth>
                <AuditPage />
              </RequireAuth>
            }
          />
          <Route
            path="/admin"
            element={
              <RequireAuth>
                <AdminPage />
              </RequireAuth>
            }
          />
          <Route
            path="/map"
            element={
              <RequireAuth>
                <MapPage />
              </RequireAuth>
            }
          />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </div>
    </div>
  );
}

function RequireAuthLoose({ children }: { children: React.ReactNode }) {
  const { user, loading } = useAuth();
  if (loading) {
    return <div>Loading…</div>;
  }
  if (!user) {
    return <Navigate to="/login" replace />;
  }
  return <>{children}</>;
}
"}

