import { Link, useLocation, useNavigate } from "react-router-dom";
import { useAuth } from "../lib/AuthContext";
import { ROLE_LABELS, Role } from "../lib/types";

export default function TopBar() {
  const { user, logout, selectRole } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();

  async function handleRoleChange(e: React.ChangeEvent<HTMLSelectElement>) {
    const role = e.target.value as Role;
    await selectRole(role);
    navigate("/");
  }

  function handleSignOut() {
    logout();
    navigate("/login");
  }

  const links: { to: string; label: string; roles?: Role[] }[] = [
    { to: "/", label: "Dashboard" },
    { to: "/serviceability", label: "Serviceability", roles: ["requester"] },
    { to: "/new-request", label: "New Request", roles: ["requester"] },
    { to: "/monitor", label: "Monitor", roles: ["administrator", "dispatcher"] },
    { to: "/audit", label: "Audit", roles: ["administrator", "dispatcher"] },
    { to: "/admin", label: "Admin", roles: ["administrator"] },
    { to: "/map", label: "Map" },
  ];

  return (
    <div>
      <div className="top-bar">
        <h1>Lab Sample Pickup &amp; Delivery</h1>
        <div className="top-bar-actions">
          {user && (
            <>
              <span aria-label="signed-in-username">{user.username}</span>
              {user.roles.length > 0 && (
                <select
                  aria-label="active-role-selector"
                  className="role-select"
                  value={user.activeRole || ""}
                  onChange={handleRoleChange}
                >
                  <option value="" disabled>
                    Select role
                  </option>
                  {user.roles.map((r) => (
                    <option key={r} value={r}>
                      {ROLE_LABELS[r] ?? r}
                    </option>
                  ))}
                </select>
              )}
              <button aria-label="sign-out" className="secondary" onClick={handleSignOut}>
                Sign out
              </button>
            </>
          )}
        </div>
      </div>
      {user && user.activeRole && (
        <nav className="nav-links">
          {links
            .filter((l) => !l.roles || l.roles.includes(user.activeRole as Role))
            .map((l) => (
              <Link key={l.to} to={l.to} className={location.pathname === l.to ? "active" : ""}>
                {l.label}
              </Link>
            ))}
        </nav>
      )}
    </div>
  );
}
"}

{"command":"create","path":"/workspace/frontend/src/pages/LoginPage.tsx","file_text":"import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../lib/AuthContext";
import { ApiError } from "../lib/api";

export default function LoginPage() {
  const { login } = useAuth();
  const navigate = useNavigate();
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setSubmitting(true);
    try {
      await login(username, password);
      navigate("/");
    } catch (err) {
      if (err instanceof ApiError) {
        setError(err.message || "Invalid username or password");
      } else {
        setError("Something went wrong. Please try again.");
      }
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="card" style={{ maxWidth: 420, margin: "3rem auto" }}>
      <h2>Sign in</h2>
      {error && <div className="error-banner" role="alert">{error}</div>}
      <form onSubmit={handleSubmit}>
        <div className="field">
          <label htmlFor="username">Username</label>
          <input
            id="username"
            name="username"
            autoComplete="username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            required
          />
        </div>
        <div className="field" style={{ marginTop: "0.75rem" }}>
          <label htmlFor="password">Password</label>
          <input
            id="password"
            name="password"
            type="password"
            autoComplete="current-password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />
        </div>
        <button type="submit" style={{ marginTop: "1rem" }} disabled={submitting} aria-label="sign-in-submit">
          {submitting ? "Signing in…" : "Sign in"}
        </button>
      </form>
    </div>
  );
}
"}

