const WORKER_ROLES = ["collection_professional", "delivery_partner", "node_handler", "laboratory_team"];

function itemKey(item: RoleWorkItem): string {
  return String(item.assignmentId ?? item.journeyId ?? item.sampleId ?? Math.random());
}

function itemLabel(item: RoleWorkItem): string {
  if (item.kind === "sample") return `Sample ${item.sampleId}`;
  if (item.kind === "journey") return `Journey ${item.journeyId}`;
  return `${item.kind} assignment ${item.assignmentId} (sample ${item.sampleId})`;
}

export default function DashboardPage() {
  const { user } = useAuth();
  const [work, setWork] = useState<RoleWork | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [tab, setTab] = useState<"pending" | "inProgress" | "completed">("pending");
  const [busyId, setBusyId] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    try {
      const data = await api.post<RoleWork>("/list-role-work", { role: user?.activeRole });
      setWork(data);
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Failed to load work");
    }
  }, [user?.activeRole]);

  useEffect(() => {
    load();
  }, [load]);

  async function act(action: "accept" | "decline", item: RoleWorkItem) {
    if (!item.assignmentId) return;
    setBusyId(itemKey(item));
    setMessage(null);
    setError(null);
    try {
      if (action === "accept") {
        await api.post("/accept-assignment", {
          assignmentId: item.assignmentId,
          idempotencyKey: newIdempotencyKey(),
        });
        setMessage("Assignment accepted.");
      } else {
        await api.post("/decline-assignment", {
          assignmentId: item.assignmentId,
          reason: "unavailable",
          idempotencyKey: newIdempotencyKey(),
        });
        setMessage("Assignment declined.");
      }
      await load();
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Action failed");
    } finally {
      setBusyId(null);
    }
  }

  if (!user) return null;
  const isWorker = WORKER_ROLES.includes(user.activeRole as string);
  const items = work ? work[tab] : [];

  return (
    <div>
      <div className="card">
        <h2>My work — {user.activeRole}</h2>
        {error && <div className="error-banner" role="alert">{error}</div>}
        {message && <div className="success-banner">{message}</div>}
        <div className="tabs">
          {(["pending", "inProgress", "completed"] as const).map((t) => (
            <button
              key={t}
              className={tab === t ? "active" : ""}
              onClick={() => setTab(t)}
              aria-label={`work-tab-${t}`}
            >
              {t === "pending" ? "Current (pending)" : t === "inProgress" ? "Current (in progress)" : "Past (completed)"}
            </button>
          ))}
        </div>
        {!work && !error && <p>Loading…</p>}
        {work && items.length === 0 && <p>No items in this view.</p>}
        {work && items.length > 0 && (
          <table>
            <thead>
              <tr>
                <th>Type</th>
                <th>Reference</th>
                <th>Status</th>
                {isWorker && tab === "pending" && <th>Actions</th>}
                <th>History</th>
              </tr>
            </thead>
            <tbody>
              {items.map((item) => (
                <tr key={itemKey(item)}>
                  <td>{item.kind}</td>
                  <td>
                    {item.sampleId ? (
                      <Link to={`/samples/${item.sampleId}`}>{itemLabel(item)}</Link>
                    ) : (
                      itemLabel(item)
                    )}
                  </td>
                  <td>{item.status}</td>
                  {isWorker && tab === "pending" && (
                    <td>
                      {item.status === "offered" && (
                        <div className="field-row">
                          <button
                            aria-label={`accept-assignment-${item.assignmentId}`}
                            disabled={busyId === itemKey(item)}
                            onClick={() => act("accept", item)}
                          >
                            Accept
                          </button>
                          <button
                            className="secondary"
                            aria-label={`decline-assignment-${item.assignmentId}`}
                            disabled={busyId === itemKey(item)}
                            onClick={() => act("decline", item)}
                          >
                            Decline
                          </button>
                        </div>
                      )}
                    </td>
                  )}
                  <td>
                    {Array.isArray(item.history) && item.history.length > 0 ? (
                      <details>
                        <summary>{item.history.length} events</summary>
                        <ul className="timeline">
                          {item.history.map((h) => (
                            <li key={h.eventId}>
                              {h.occurredAt} — {h.action} ({h.success ? "ok" : "failed"})
                            </li>
                          ))}
                        </ul>
                      </details>
                    ) : (
                      "—"
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}
"}

{"command":"create","path":"/workspace/frontend/src/pages/ServiceabilityPage.tsx","file_text":"import React, { useEffect, useState } from "react";
import { api, ApiError } from "../lib/api";

interface ServiceabilityRegion {
  locationId: string;
  name: string;
  latitude: number;
  longitude: number;
  coverageKm: number;
}

interface SnapshotData {
  version: number;
  status: string;
  computedAt: string;
  networkRevision: number;
  regions: ServiceabilityRegion[];
  activeCollectionPointCount: number;
}

interface CheckResult {
  serviceable: boolean;
  reason: string;
  targetLaboratoryId?: string;
  estimatedArrivalAt?: string;
  serviceabilityVersion: number;
}

export default function ServiceabilityPage() {
  const [latitude, setLatitude] = useState("12.9716");
  const [longitude, setLongitude] = useState("77.5946");
  const [originType, setOriginType] = useState("home");
  const [sampleTypeId, setSampleTypeId] = useState("");
  const [requestedAt, setRequestedAt] = useState("");
  const [deliveryDeadline, setDeliveryDeadline] = useState("");
  const [earliestCollectionAt, setEarliestCollectionAt] = useState("");
  const [latestCollectionAt, setLatestCollectionAt] = useState("");
  const [result, setResult] = useState<CheckResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [snapshot, setSnapshot] = useState<SnapshotData | null>(null);

  useEffect(() => {
    api
      .post<SnapshotData>("/read-serviceability-snapshot", {})
      .then(setSnapshot)
      .catch(() => setSnapshot(null));
  }, []);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setResult(null);
    setSubmitting(true);
    try {
      const body: Record<string, unknown> = {
        origin: { latitude: Number(latitude), longitude: Number(longitude) },
        originType,
        sampleTypeId,
        requestedAt,
        deliveryDeadline,
      };
      if (earliestCollectionAt) body.earliestCollectionAt = earliestCollectionAt;
      if (latestCollectionAt) body.latestCollectionAt = latestCollectionAt;
      const data = await api.post<CheckResult>("/check-serviceability", body);
      setResult(data);
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Serviceability check failed");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div>
      <div className="card">
        <h2>Serviceability check</h2>
        <p>This is a dry run — it never creates a request, sample, journey or reservation.</p>
        {error && <div className="error-banner" role="alert">{error}</div>}
        <form onSubmit={handleSubmit}>
          <div className="field-row">
            <div className="field">
              <label htmlFor="sv-lat">Latitude</label>
              <input id="sv-lat" value={latitude} onChange={(e) => setLatitude(e.target.value)} required />
            </div>
            <div className="field">
              <label htmlFor="sv-lon">Longitude</label>
              <input id="sv-lon" value={longitude} onChange={(e) => setLongitude(e.target.value)} required />
            </div>
            <div className="field">
              <label htmlFor="sv-origin-type">Origin type</label>
              <select id="sv-origin-type" value={originType} onChange={(e) => setOriginType(e.target.value)}>
                <option value="home">Home</option>
                <option value="clinic">Clinic</option>
                <option value="node">Node</option>
              </select>
            </div>
          </div>
          <div className="field-row">
            <div className="field">
              <label htmlFor="sv-sample-type">Sample type ID</label>
              <input
                id="sv-sample-type"
                value={sampleTypeId}
                onChange={(e) => setSampleTypeId(e.target.value)}
                placeholder="uuid"
                required
              />
            </div>
            <div className="field">
              <label htmlFor="sv-requested-at">Requested at</label>
              <input
                id="sv-requested-at"
                type="datetime-local"
                value={requestedAt}
                onChange={(e) => setRequestedAt(e.target.value)}
                required
              />
            </div>
            <div className="field">
              <label htmlFor="sv-deadline">Delivery deadline</label>
              <input
                id="sv-deadline"
                type="datetime-local"
                value={deliveryDeadline}
                onChange={(e) => setDeliveryDeadline(e.target.value)}
                required
              />
            </div>
          </div>
          <div className="field-row">
            <div className="field">
              <label htmlFor="sv-earliest">Earliest collection</label>
              <input
                id="sv-earliest"
                type="datetime-local"
                value={earliestCollectionAt}
                onChange={(e) => setEarliestCollectionAt(e.target.value)}
              />
            </div>
            <div className="field">
              <label htmlFor="sv-latest">Latest collection</label>
              <input
                id="sv-latest"
                type="datetime-local"
                value={latestCollectionAt}
                onChange={(e) => setLatestCollectionAt(e.target.value)}
              />
            </div>
          </div>
          <button type="submit" disabled={submitting} aria-label="check-serviceability-submit">
            {submitting ? "Checking…" : "Check serviceability"}
          </button>
        </form>
        {result && (
          <div className={result.serviceable ? "success-banner" : "error-banner"} aria-label="serviceability-result">
            <strong>{result.serviceable ? "Serviceable" : "Not serviceable"}</strong> — reason: {result.reason}
            {result.targetLaboratoryId && <div>Target laboratory: {result.targetLaboratoryId}</div>}
            {result.estimatedArrivalAt && <div>Estimated arrival: {result.estimatedArrivalAt}</div>}
            <div>Serviceability version: {result.serviceabilityVersion}</div>
          </div>
        )}
      </div>
      {snapshot && (
        <div className="card">
          <h3>Current serviceability coverage (version {snapshot.version})</h3>
          <p>Active collection points: {snapshot.activeCollectionPointCount}</p>
          <table>
            <thead>
              <tr>
                <th>Location</th>
                <th>Coverage (km)</th>
                <th>Coordinates</th>
              </tr>
            </thead>
            <tbody>
              {snapshot.regions.map((rgn) => (
                <tr key={rgn.locationId}>
                  <td>{rgn.name}</td>
                  <td>{rgn.coverageKm}</td>
                  <td>{rgn.latitude.toFixed(4)}, {rgn.longitude.toFixed(4)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
"}

{"command":"create","path":"/workspace/frontend/src/pages/NewRequestPage.tsx","file_text":"import React, { useState } from "react";
