{"command":"create","path":"/workspace/frontend/src/pages/SampleDetailPage.tsx","file_text":"import React, { useCallback, useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { api, ApiError, newIdempotencyKey } from "../lib/api";
import { useAuth } from "../lib/AuthContext";
import { SampleLifecycle, SampleState } from "../lib/types";

const WORKER_ROLES = ["collection_professional", "delivery_partner", "node_handler", "laboratory_team"];

export default function SampleDetailPage() {
  const { sampleId } = useParams<{ sampleId: string }>();
  const { user } = useAuth();
  const [state, setState] = useState<SampleState | null>(null);
  const [lifecycle, setLifecycle] = useState<SampleLifecycle | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);

  const [assignmentId, setAssignmentId] = useState("");
  const [containerType, setContainerType] = useState("");
  const [observedTemperatureC, setObservedTemperatureC] = useState("");
  const [latitude, setLatitude] = useState("");
  const [longitude, setLongitude] = useState("");

  const load = useCallback(async () => {
    if (!sampleId) return;
    setError(null);
    try {
      const s = await api.get<SampleState>(`/read-sample-state/${sampleId}`);
      setState(s);
      if (s.activeAssignmentIds && s.activeAssignmentIds.length > 0 && !assignmentId) {
        setAssignmentId(s.activeAssignmentIds[0]);
      }
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Failed to load sample");
    }
    try {
      const l = await api.post<SampleLifecycle>("/read-sample-lifecycle", { sampleId });
      setLifecycle(l);
    } catch {
      setLifecycle(null);
    }
  }, [sampleId, assignmentId]);

  useEffect(() => {
    load();
  }, [load]);

  async function recordCheckpoint(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setMessage(null);
    try {
      await api.post("/record-handling-checkpoint", {
        sampleId,
        assignmentId,
        containerType,
        observedTemperatureC: Number(observedTemperatureC),
        recordedAt: new Date().toISOString(),
        idempotencyKey: newIdempotencyKey(),
      });
      setMessage("Checkpoint recorded.");
      await load();
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Failed to record checkpoint");
    }
  }

  async function recordLocation(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setMessage(null);
    try {
      await api.post("/record-worker-location", {
        assignmentId,
        coordinate: { latitude: Number(latitude), longitude: Number(longitude) },
        sequence: Date.now(),
        recordedAt: new Date().toISOString(),
      });
      setMessage("Location recorded.");
      await load();
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Failed to record location");
    }
  }

  if (!sampleId) return null;
  const isWorker = user && WORKER_ROLES.includes(user.activeRole as string);
  const exception = lifecycle?.exception;

  return (
    <div>
      {error && <div className="error-banner" role="alert">{error}</div>}
      {message && <div className="success-banner">{message}</div>}
      <div className="card">
        <h2>Sample {sampleId}</h2>
        {!state && <p>Loading…</p>}
        {state && (
          <>
            <p>
              <span className="tag" aria-label="sample-status">{state.state?.status ?? lifecycle?.status}</span>{" "}
              {state.locationStale && <span className="tag stale" aria-label="location-stale">stale location</span>}
              {exception && <span className="tag exception" aria-label="sample-exception">exception</span>}
            </p>
            <table>
              <tbody>
                <tr><th>Origin type</th><td>{state.originType}</td></tr>
                <tr><th>Origin</th><td>{state.origin.latitude}, {state.origin.longitude}</td></tr>
                <tr><th>Delivery deadline</th><td>{state.deliveryDeadline}</td></tr>
                <tr><th>Serviceability</th><td>{state.serviceability}</td></tr>
                <tr><th>Active journey</th><td>{state.activeJourneyId ?? "—"}</td></tr>
                <tr><th>Current holder</th><td>{lifecycle?.currentHolderId ?? "—"}</td></tr>
                <tr>
                  <th>Latest location</th>
                  <td>
                    {state.latestLocation
                      ? `${state.latestLocation.latitude}, ${state.latestLocation.longitude} (recorded ${state.locationRecordedAt ?? "?"})`
                      : "unknown"}
                  </td>
                </tr>
              </tbody>
            </table>
          </>
        )}
      </div>

      {isWorker && state && (
        <div className="card">
          <h3>Record checkpoint / location</h3>
          <div className="field">
            <label htmlFor="assignment-id">Assignment ID</label>
            <input id="assignment-id" value={assignmentId} onChange={(e) => setAssignmentId(e.target.value)} />
          </div>
          <form onSubmit={recordCheckpoint}>
            <div className="field-row">
              <div className="field">
                <label htmlFor="checkpoint-container">Container type</label>
                <input
                  id="checkpoint-container"
                  value={containerType}
                  onChange={(e) => setContainerType(e.target.value)}
                  required
                />
              </div>
              <div className="field">
                <label htmlFor="checkpoint-temp">Observed temperature (°C)</label>
                <input
                  id="checkpoint-temp"
                  type="number"
                  value={observedTemperatureC}
                  onChange={(e) => setObservedTemperatureC(e.target.value)}
                  required
                />
              </div>
            </div>
            <button type="submit" aria-label="record-checkpoint-submit">Record checkpoint</button>
          </form>
          <form onSubmit={recordLocation} style={{ marginTop: "0.75rem" }}>
            <div className="field-row">
              <div className="field">
                <label htmlFor="loc-lat">Latitude</label>
                <input id="loc-lat" value={latitude} onChange={(e) => setLatitude(e.target.value)} required />
              </div>
              <div className="field">
                <label htmlFor="loc-lon">Longitude</label>
                <input id="loc-lon" value={longitude} onChange={(e) => setLongitude(e.target.value)} required />
              </div>
            </div>
            <button type="submit" aria-label="record-location-submit">Record location</button>
          </form>
        </div>
      )}

      <div className="card">
        <h3>Status history</h3>
        {state && state.timeline.length === 0 && <p>No history yet.</p>}
        {state && state.timeline.length > 0 && (
          <ul className="timeline" aria-label="sample-status-timeline">
            {state.timeline.map((t) => (
              <li key={t.eventId}>
                {t.occurredAt} — {t.action} — {t.success ? "ok" : "failed"} (by {t.role})
              </li>
            ))}
          </ul>
        )}
      </div>
