{"command":"create","path":"/workspace/frontend/src/pages/MonitorPage.tsx","file_text":"import React, { useCallback, useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { api, ApiError } from "../lib/api";
import { OperationsState } from "../lib/types";

type Category = "samples" | "workers" | "locations" | "connections" | "routes" | "handoffs" | "delays" | "exceptions";

const CATEGORIES: Category[] = ["samples", "workers", "locations", "connections", "routes", "handoffs", "delays", "exceptions"];

export default function MonitorPage() {
  const [ops, setOps] = useState<OperationsState | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [category, setCategory] = useState<Category>("samples");

  const load = useCallback(async () => {
    setError(null);
    try {
      const data = await api.post<OperationsState>("/read-operations-state", {});
      setOps(data);
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Failed to load operations state");
    }
  }, []);

  useEffect(() => {
    load();
    const id = setInterval(load, 15000);
    return () => clearInterval(id);
  }, [load]);

  return (
    <div>
      <div className="card">
        <h2>Operations monitor</h2>
        {error && <div className="error-banner" role="alert">{error}</div>}
        <div className="tabs" aria-label="monitor-categories">
          {CATEGORIES.map((c) => (
            <button key={c} className={category === c ? "active" : ""} onClick={() => setCategory(c)} aria-label={`monitor-tab-${c}`}>
              {c} {ops ? `(${(ops[c] as unknown[])?.length ?? 0})` : ""}
            </button>
          ))}
        </div>
        {!ops && !error && <p>Loading…</p>}
        {ops && (
          <div aria-label={`monitor-category-${category}`}>
            {category === "samples" && (
              <table>
                <thead>
                  <tr><th>Sample</th><th>Status</th><th>Holder</th><th>Stale?</th></tr>
                </thead>
                <tbody>
                  {ops.samples.map((s) => (
                    <tr key={String(s.sampleId)}>
                      <td><Link to={`/samples/${s.sampleId}`}>{String(s.sampleId)}</Link></td>
                      <td>{String(s.status)}</td>
                      <td>{String(s.currentHolderId ?? "—")}</td>
                      <td>{s.locationStale ? <span className="tag stale">stale</span> : "fresh"}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
            {category === "workers" && (
              <table>
                <thead>
                  <tr><th>Worker</th><th>Roles</th><th>Available</th><th>Assignments</th><th>Stale?</th></tr>
                </thead>
                <tbody>
                  {ops.workers.map((w) => (
                    <tr key={String(w.workerId)}>
                      <td>{String(w.fullName ?? w.workerId)}</td>
                      <td>{Array.isArray(w.roles) ? (w.roles as string[]).join(", ") : ""}</td>
                      <td>{w.available ? "yes" : "no"}</td>
                      <td>{String(w.assignmentCount ?? 0)}</td>
                      <td>{w.locationStale ? <span className="tag stale">stale</span> : "fresh"}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
            {category === "locations" && (
              <table>
                <thead>
                  <tr><th>Name</th><th>Active</th><th>Functions</th><th>Capacity (reg/cooled avail)</th></tr>
                </thead>
                <tbody>
                  {ops.locations.map((l) => (
                    <tr key={l.id}>
                      <td>{l.name}</td>
                      <td>{l.active ? "active" : "inactive"}</td>
                      <td>{Object.entries(l.functions).filter(([, v]) => v).map(([k]) => k).join(", ")}</td>
                      <td>
                        {l.capacity ? `${l.capacity.availableUnits}/${l.capacity.cooledAvailableUnits}` : "—"}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
            {category === "connections" && (
              <table>
                <thead>
                  <tr><th>From</th><th>To</th><th>Travel (min)</th><th>Cooled</th><th>Active</th></tr>
                </thead>
                <tbody>
                  {ops.connections.map((c) => (
                    <tr key={c.id}>
                      <td>{c.fromLocationId}</td>
                      <td>{c.toLocationId}</td>
                      <td>{c.travelMinutes}</td>
                      <td>{c.cooled ? "yes" : "no"}</td>
                      <td>{c.active ? "active" : "inactive"}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
            {(category === "routes" || category === "handoffs" || category === "delays" || category === "exceptions") && (
              <pre>{JSON.stringify(ops[category], null, 2)}</pre>
            )}
          </div>
        )}
        {ops && (
          <p>
            Assignment count spread: {ops.assignmentCountSpread} · Ineligible assignments: {ops.ineligibleAssignmentCount}
          </p>
        )}
      </div>
    </div>
  );
}
"}

{"command":"create","path":"/workspace/frontend/src/pages/AuditPage.tsx","file_text":"import React, { useState } from "react";
import { api, ApiError } from "../lib/api";
import { AuditSearchResult } from "../lib/types";

export default function AuditPage() {
  const [query, setQuery] = useState("");
  const [entityType, setEntityType] = useState("");
  const [entityId, setEntityId] = useState("");
  const [action, setAction] = useState("");
  const [result, setResult] = useState<AuditSearchResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  async function search(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setSubmitting(true);
    try {
      const body: Record<string, unknown> = { order: "newest_first", limit: 200 };
      if (query) body.query = query;
      if (entityType) body.entityType = entityType;
      if (entityId) body.entityId = entityId;
      if (action) body.action = action;
      const data = await api.post<AuditSearchResult>("/search-audit-trail", body);
      setResult(data);
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Search failed");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="card">
      <h2>Audit trail</h2>
      {error && <div className="error-banner" role="alert">{error}</div>}
      <form onSubmit={search}>
        <div className="field-row">
          <div className="field">
            <label htmlFor="audit-query">Free text</label>
            <input id="audit-query" value={query} onChange={(e) => setQuery(e.target.value)} />
          </div>
          <div className="field">
            <label htmlFor="audit-entity-type">Entity type</label>
            <input id="audit-entity-type" value={entityType} onChange={(e) => setEntityType(e.target.value)} placeholder="sample / request / journey" />
          </div>
          <div className="field">
            <label htmlFor="audit-entity-id">Entity ID</label>
            <input id="audit-entity-id" value={entityId} onChange={(e) => setEntityId(e.target.value)} />
          </div>
          <div className="field">
            <label htmlFor="audit-action">Action</label>
            <input id="audit-action" value={action} onChange={(e) => setAction(e.target.value)} />
          </div>
        </div>
        <button type="submit" disabled={submitting} aria-label="audit-search-submit">
          {submitting ? "Searching…" : "Search"}
        </button>
      </form>
      {result && (
        <>
          <p>{result.total} total, showing {result.returned}</p>
          <table aria-label="audit-results">
            <thead>
              <tr>
                <th>Time</th><th>Actor</th><th>Role</th><th>Action</th><th>Entity</th><th>Outcome</th>
              </tr>
            </thead>
            <tbody>
              {result.entries.map((e) => (
                <tr key={e.auditId}>
                  <td>{e.occurredAt}</td>
                  <td>{e.actorId}</td>
                  <td>{e.actorRole}</td>
                  <td>{e.action}</td>
                  <td>{e.entityType}:{e.entityId}</td>
                  <td>{e.success ? "success" : "failed"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </>
      )}
    </div>
  );
}
"}

