{"command":"create","path":"/workspace/frontend/src/pages/MapPage.tsx","file_text":"import React, { useEffect, useRef, useState } from "react";
import maplibregl, { Map as MLMap, Marker } from "maplibre-gl";
import { Protocol } from "pmtiles";
import { api, ApiError } from "../lib/api";
import { OperationsState } from "../lib/types";

const STYLE_URL = "/map-assets/style.json";

export default function MapPage() {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const mapRef = useRef<MLMap | null>(null);
  const markersRef = useRef<Marker[]>([]);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const protocol = new Protocol();
    maplibregl.addProtocol("pmtiles", protocol.tile);
    if (!containerRef.current) return;
    const map = new maplibregl.Map({
      container: containerRef.current,
      style: STYLE_URL,
      center: [77.5946, 12.9716],
      zoom: 10,
    });
    mapRef.current = map;
    return () => {
      map.remove();
      maplibregl.removeProtocol("pmtiles");
    };
  }, []);

  useEffect(() => {
    let cancelled = false;
    async function load() {
      try {
        const data = await api.post<OperationsState>("/read-operations-state", {});
        if (cancelled || !mapRef.current) return;
        markersRef.current.forEach((m) => m.remove());
        markersRef.current = [];
        const map = mapRef.current;
        data.locations.forEach((loc) => {
          if (!loc.coordinate) return;
          const el = document.createElement("div");
          el.className = "map-marker map-marker-location";
          el.title = loc.name;
          const marker = new maplibregl.Marker({ element: el })
            .setLngLat([loc.coordinate.longitude, loc.coordinate.latitude])
            .setPopup(new maplibregl.Popup().setText(loc.name))
            .addTo(map);
          markersRef.current.push(marker);
        });
        data.workers.forEach((w) => {
          const loc = (w.latestLocation as { latitude: number; longitude: number } | undefined) ?? undefined;
          if (!loc) return;
          const el = document.createElement("div");
          el.className = "map-marker map-marker-worker";
          el.title = String(w.fullName ?? w.workerId);
          const marker = new maplibregl.Marker({ element: el, color: "#2563eb" })
            .setLngLat([loc.longitude, loc.latitude])
            .setPopup(new maplibregl.Popup().setText(String(w.fullName ?? w.workerId)))
            .addTo(map);
          markersRef.current.push(marker);
        });
      } catch (err) {
        setError(err instanceof ApiError ? err.message : "Failed to load map data");
      }
    }
    load();
    const id = setInterval(load, 15000);
    return () => {
      cancelled = true;
      clearInterval(id);
    };
  }, []);

  return (
    <div className="card">
      <h2>Live map</h2>
      {error && <div className="error-banner" role="alert">{error}</div>}
      <div ref={containerRef} data-testid="map-container" style={{ width: "100%", height: "560px" }} />
    </div>
  );
}
"}

